'use strict';
// GENERATED by scripts/build-pages.js from public/*. Do not edit by hand.
module.exports = {
  hash: "13791df32866a390b876fc52f8d85043f54a67e7df19c605ccfc6c333b003abb",
  files: {"index.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Next Level notes — Study Notes &amp; E-books</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Source+Serif+4:wght@500;600;700&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<script src=\"/config.js\"></script>\n<script src=\"https://accounts.google.com/gsi/client\" async defer></script>\n<style>\n  :root{\n    --ink:#1B2333;\n    --ink-soft:#2B3650;\n    --paper:#F8F8F5;\n    --paper-raised:#FFFFFF;\n    --line:#E1E1DB;\n    --muted:#65697A;\n    --amber:#E8A33D;\n    --amber-dark:#C7842A;\n    --mint:#6FA98D;\n    --highlight:#F4D35E;\n    --danger:#C1523E;\n    --radius:10px;\n    font-size:16px;\n  }\n  *{box-sizing:border-box;}\n  body{\n    margin:0;\n    background:var(--paper);\n    color:var(--ink);\n    font-family:'Inter',sans-serif;\n    line-height:1.5;\n  }\n  h1,h2,h3,.serif{\n    font-family:'Source Serif 4',serif;\n    margin:0;\n    color:var(--ink);\n  }\n  a{color:inherit;}\n  button{font-family:inherit;cursor:pointer;}\n  .wrap{max-width:1120px;margin:0 auto;padding:0 24px;}\n\n  /* HEADER */\n  header{\n    position:sticky;top:0;z-index:40;\n    background:var(--paper);\n    border-bottom:1px solid var(--line);\n  }\n  .headbar{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;max-width:1120px;margin:0 auto;}\n  .brand{display:flex;align-items:center;gap:10px;font-family:'Source Serif 4',serif;font-weight:600;font-size:22px;}\n  .brand-mark{width:30px;height:30px;flex-shrink:0;}\n  .nav-actions{display:flex;align-items:center;gap:14px;}\n  .icon-btn{\n    position:relative;background:none;border:1px solid var(--line);border-radius:8px;\n    padding:8px 12px;font-size:14px;font-weight:500;color:var(--ink);display:flex;align-items:center;gap:6px;\n  }\n  .icon-btn:hover{border-color:var(--ink);}\n  .badge{\n    background:var(--amber);color:var(--ink);font-size:11px;font-weight:700;\n    border-radius:99px;min-width:18px;height:18px;display:inline-flex;align-items:center;justify-content:center;padding:0 5px;\n  }\n  .ghost-link{background:none;border:none;color:var(--muted);font-size:14px;text-decoration:underline;text-underline-offset:3px;}\n\n  /* HERO */\n  .hero{padding:72px 24px 60px;position:relative;overflow:hidden;}\n  .hero::before{\n    content:\"\";position:absolute;top:-120px;right:-80px;width:420px;height:420px;border-radius:50%;\n    background:radial-gradient(circle, rgba(232,163,61,0.16), transparent 70%);pointer-events:none;\n  }\n  .hero-inner{max-width:1120px;margin:0 auto;display:grid;grid-template-columns:1.1fr 0.9fr;gap:48px;align-items:center;position:relative;}\n  .hero h1{font-size:46px;line-height:1.14;font-weight:600;max-width:520px;letter-spacing:-0.01em;}\n  .hero p{color:var(--muted);font-size:17px;max-width:440px;margin-top:16px;}\n  .hero-ctas{margin-top:30px;display:flex;gap:12px;}\n  .btn{\n    border:none;border-radius:8px;padding:12px 22px;font-size:15px;font-weight:600;\n    transition:transform .15s ease, background .15s ease, box-shadow .15s ease, color .15s ease;\n  }\n  .btn:active{transform:translateY(1px);}\n  .btn-primary{background:var(--ink);color:var(--paper);box-shadow:0 1px 2px rgba(27,35,51,0.15);}\n  .btn-primary:hover{background:var(--ink-soft);box-shadow:0 4px 14px rgba(27,35,51,0.25);transform:translateY(-1px);}\n  .btn-outline{background:transparent;border:1px solid var(--ink);color:var(--ink);}\n  .btn-outline:hover{background:var(--ink);color:var(--paper);transform:translateY(-1px);}\n  .btn-amber{background:var(--amber);color:var(--ink);box-shadow:0 1px 2px rgba(199,132,42,0.25);}\n  .btn-amber:hover{background:var(--amber-dark);box-shadow:0 4px 14px rgba(199,132,42,0.35);transform:translateY(-1px);}\n  .btn-block{width:100%;}\n  .btn[disabled]{opacity:0.55;cursor:not-allowed;transform:none !important;box-shadow:none !important;}\n\n  /* CATEGORY CHIPS */\n  .chips{display:flex;gap:10px;flex-wrap:wrap;padding:0 24px 32px;max-width:1120px;margin:0 auto;}\n  .chip{\n    border:1px solid var(--line);background:var(--paper-raised);border-radius:99px;\n    padding:8px 16px;font-size:14px;font-weight:500;color:var(--muted);\n    transition:all .15s ease;\n  }\n  .chip:hover{border-color:var(--ink);color:var(--ink);}\n  .chip.active{background:var(--ink);color:var(--paper);border-color:var(--ink);box-shadow:0 2px 8px rgba(27,35,51,0.2);}\n\n  /* PRODUCT GRID */\n  .grid{\n    max-width:1120px;margin:0 auto;padding:0 24px 80px;\n    display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:24px;\n  }\n  .card{\n    background:var(--paper-raised);border:1px solid var(--line);border-radius:var(--radius);\n    overflow:hidden;display:flex;flex-direction:column;cursor:pointer;\n    transition:transform .18s ease, box-shadow .18s ease, border-color .18s ease;\n  }\n  .card:focus-visible{outline:3px solid rgba(232,163,61,.45);outline-offset:3px;}\n  .card:hover{transform:translateY(-4px);box-shadow:0 12px 28px rgba(27,35,51,0.12);border-color:transparent;}\n  .cover{\n    height:148px;position:relative;display:flex;align-items:flex-end;padding:14px;\n    background-image:repeating-linear-gradient(180deg, rgba(255,255,255,0.16) 0 1px, transparent 1px 22px),\n      linear-gradient(160deg, rgba(255,255,255,0.08), rgba(0,0,0,0.08));\n  }\n  .cover .tag{\n    background:rgba(255,255,255,0.92);color:var(--ink);font-size:11px;font-weight:700;\n    padding:5px 10px;border-radius:6px;letter-spacing:0.02em;box-shadow:0 2px 6px rgba(0,0,0,0.12);\n  }\n  .cover.has-image{background:#eef0f3;padding:0;align-items:flex-end;}\n  .cover.has-image::after{content:\"\";position:absolute;inset:0;background:linear-gradient(180deg,transparent 50%,rgba(0,0,0,.18));pointer-events:none;}\n  .cover-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;}\n  .cover.has-image .tag{position:relative;z-index:2;margin:14px;}\n  .cart-thumb{width:54px;height:66px;object-fit:cover;border-radius:7px;border:1px solid var(--line);background:#eef0f3;flex:0 0 auto;}\n  .upi-qr{width:min(260px,100%);height:auto;display:block;margin:12px auto;border-radius:12px;border:1px solid var(--line);background:#fff;padding:8px;}\n  .qr-note{text-align:center;font-size:12.5px;color:var(--muted);margin-top:4px;}\n  .card-body{padding:18px;display:flex;flex-direction:column;gap:6px;flex:1;}\n  .card-body h3{font-size:17px;font-weight:600;letter-spacing:-0.005em;}\n  .card-body .subject{color:var(--muted);font-size:13px;}\n  .card-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:auto;padding-top:14px;flex-wrap:wrap;}\n  .price{font-family:'Source Serif 4',serif;font-weight:600;font-size:19px;}\n  .product-actions{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end;}\n  .add-btn,.buy-btn{\n    border-radius:7px;padding:8px 12px;font-size:13px;font-weight:600;\n    display:inline-flex;align-items:center;justify-content:center;gap:6px;transition:background .15s ease, transform .15s ease,border-color .15s ease;\n  }\n  .add-btn{background:var(--ink);color:var(--paper);border:1px solid var(--ink);}\n  .buy-btn{background:var(--paper-raised);color:var(--ink);border:1px solid var(--ink);}\n  .add-btn:hover{background:var(--ink-soft);transform:translateY(-1px);}\n  .buy-btn:hover{background:#F0F2F5;transform:translateY(-1px);}\n  .add-btn:active,.buy-btn:active{transform:translateY(0);}\n  .empty-note{color:var(--muted);text-align:center;padding:60px 20px;grid-column:1/-1;}\n\n  /* CART DRAWER */\n  .overlay{\n    position:fixed;inset:0;background:rgba(27,35,51,0.35);z-index:60;\n    opacity:0;pointer-events:none;transition:opacity .2s ease;\n  }\n  .overlay.open{opacity:1;pointer-events:auto;}\n  .drawer{\n    position:fixed;top:0;right:0;height:100%;width:min(420px,92vw);\n    background:var(--paper);z-index:70;transform:translateX(100%);\n    transition:transform .28s cubic-bezier(.32,.72,0,1);display:flex;flex-direction:column;\n    border-left:1px solid var(--line);box-shadow:-8px 0 32px rgba(27,35,51,0.1);\n  }\n  .drawer.open{transform:translateX(0);}\n  .drawer-head{padding:20px 22px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;}\n  .drawer-body{flex:1;overflow-y:auto;padding:16px 22px;display:flex;flex-direction:column;gap:14px;}\n  .cart-item{display:flex;gap:12px;border-bottom:1px solid var(--line);padding-bottom:14px;}\n  .cart-item .swatch{width:48px;height:60px;border-radius:6px;flex-shrink:0;box-shadow:0 2px 6px rgba(0,0,0,0.15);}\n  .cart-item-info{flex:1;}\n  .cart-item-info h4{font-size:14px;font-weight:600;margin-bottom:2px;}\n  .qty-row{display:flex;align-items:center;gap:8px;margin-top:6px;}\n  .qty-btn{width:24px;height:24px;border:1px solid var(--line);background:none;border-radius:5px;font-size:13px;transition:border-color .15s ease;}\n  .qty-btn:hover{border-color:var(--ink);}\n  .remove-link{color:var(--danger);font-size:12px;background:none;border:none;text-decoration:underline;padding:0;}\n  .drawer-foot{padding:18px 22px;border-top:1px solid var(--line);}\n  .subtotal-row{display:flex;justify-content:space-between;font-size:15px;margin-bottom:14px;font-weight:600;}\n  .close-x{background:none;border:none;font-size:20px;color:var(--muted);line-height:1;width:30px;height:30px;border-radius:6px;transition:background .15s ease;}\n  .close-x:hover{background:var(--line);}\n\n  /* MODAL */\n  .modal-overlay{\n    position:fixed;inset:0;background:rgba(27,35,51,0.4);z-index:80;\n    display:flex;align-items:center;justify-content:center;padding:20px;\n    opacity:0;pointer-events:none;transition:opacity .18s ease;\n    overscroll-behavior:contain;\n  }\n  .modal-overlay.open{opacity:1;pointer-events:auto;}\n  .modal{\n    background:var(--paper-raised);border-radius:14px;max-width:420px;width:100%;\n    padding:28px;position:relative;max-height:88vh;overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;\n    box-shadow:0 24px 60px rgba(27,35,51,0.25);\n    transform:translateY(10px) scale(.98);transition:transform .2s cubic-bezier(.32,.72,0,1);\n  }\n  .modal-overlay.open .modal{transform:translateY(0) scale(1);}\n  .modal h2{font-size:22px;margin-bottom:6px;}\n  .modal .sub{color:var(--muted);font-size:14px;margin-bottom:20px;}\n  .field{margin-bottom:14px;}\n  .field label{display:block;font-size:13px;font-weight:600;margin-bottom:5px;}\n  .field input, .field select, .field textarea{\n    width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:7px;font-size:14px;font-family:inherit;background:var(--paper);\n    transition:border-color .15s ease, box-shadow .15s ease;\n  }\n  .field input:focus, .field select:focus, .field textarea:focus{\n    outline:none;border-color:var(--amber);box-shadow:0 0 0 3px rgba(232,163,61,0.2);\n  }\n  .field textarea{resize:vertical;min-height:70px;}\n  .modal-close{position:absolute;top:10px;right:10px;background:rgba(255,255,255,.96);border:1px solid var(--line);font-size:22px;color:var(--ink);width:44px;height:44px;border-radius:10px;transition:background .15s ease,transform .15s ease;z-index:12;display:grid;place-items:center;line-height:1;touch-action:manipulation;-webkit-tap-highlight-color:transparent;}\n  .modal-close:hover{background:var(--line);}\n  .modal-close:active{transform:scale(.96);}\n  body.modal-open{overflow:hidden;}\n  .divider-or{display:flex;align-items:center;gap:10px;color:var(--muted);font-size:12px;margin:16px 0;}\n  .divider-or::before,.divider-or::after{content:\"\";flex:1;height:1px;background:var(--line);}\n  .gsi-slot{display:flex;justify-content:center;min-height:40px;}\n  .setup-note{background:#FBF3E2;border:1px solid var(--highlight);border-radius:8px;padding:10px 12px;font-size:12.5px;color:var(--ink-soft);margin-top:10px;}\n  .success-box{background:#EEF6F1;border:1px solid var(--mint);border-radius:8px;padding:14px;font-size:14px;margin-top:6px;}\n  .success-box a{color:var(--ink);font-weight:600;}\n\n  .product-detail-modal{max-width:760px;}\n  .product-detail-grid{display:grid;grid-template-columns:minmax(220px,.85fr) minmax(0,1.15fr);gap:26px;align-items:start;}\n  .product-detail-media{aspect-ratio:4/3;border-radius:12px;overflow:hidden;background:#EEF0F3;border:1px solid var(--line);position:relative;}\n  .product-detail-media img{width:100%;height:100%;object-fit:cover;display:block;}\n  .product-detail-placeholder{width:100%;height:100%;display:flex;align-items:flex-end;padding:18px;color:#fff;font-weight:700;font-size:13px;background:linear-gradient(145deg,var(--ink),#53627d);}\n  .product-detail-type{display:inline-flex;padding:5px 9px;border-radius:999px;background:#F1F2F4;color:var(--ink-soft);font-size:11px;font-weight:700;margin-bottom:10px;}\n  .product-detail-title{font-size:28px !important;line-height:1.18;margin:0 48px 4px 0 !important;}\n  .product-detail-subject{color:var(--muted);font-size:14px;margin-bottom:18px;}\n  .product-detail-description{font-size:14px;color:var(--ink-soft);line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere;margin-bottom:20px;}\n  .product-detail-footer{display:flex;align-items:center;justify-content:space-between;gap:14px;border-top:1px solid var(--line);padding-top:18px;flex-wrap:wrap;}\n  .product-detail-price{font-family:'Source Serif 4',serif;font-size:26px;font-weight:700;}\n\n  .toast{\n    position:fixed;bottom:28px;left:50%;transform:translate(-50%, 12px);\n    background:var(--ink);color:var(--paper);padding:12px 22px;border-radius:8px;font-size:14px;\n    z-index:100;opacity:0;pointer-events:none;transition:opacity .2s ease, transform .2s ease;\n    box-shadow:0 10px 30px rgba(27,35,51,0.3);\n  }\n  .toast.show{opacity:1;transform:translate(-50%, 0);}\n  footer{border-top:1px solid var(--line);padding:28px 24px;text-align:center;color:var(--muted);font-size:13px;}\n  .support-footer{margin-top:8px}.support-footer a{color:var(--ink);font-weight:700;text-decoration:none}.support-footer a:hover{text-decoration:underline}\n  .support-fab{position:fixed;right:18px;bottom:18px;z-index:55;background:var(--ink);color:#fff;text-decoration:none;border-radius:999px;padding:11px 15px;font-size:13px;font-weight:700;box-shadow:0 8px 24px rgba(27,35,51,.2)}\n  .support-fab:hover{background:var(--ink-soft)}\n  .qr-loading{padding:14px;border:1px dashed var(--line);border-radius:9px;text-align:center;color:var(--muted);font-size:13px;margin-top:10px}\n  .qr-error{padding:12px 14px;border:1px solid #F0C8C4;background:#FFF2F0;color:var(--danger);border-radius:9px;font-size:13px;margin-top:10px}\n\n  .status-pill{display:inline-flex;align-items:center;padding:4px 9px;border-radius:99px;font-size:12px;font-weight:700;text-transform:capitalize;}\n  .status-pending{background:#FBF3E2;color:#8A5A16;}\n  .status-paid{background:#EEF6F1;color:#2F6D4C;}\n  .status-delivered{background:#EAF1FA;color:#315F91;}\n  .status-rejected{background:#FBEDEA;color:#9E3B2E;}\n  .order-list{display:flex;flex-direction:column;gap:12px;}\n  .order-card{border:1px solid var(--line);border-radius:10px;padding:15px;background:var(--paper);}\n  .order-card-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:8px;}\n  .order-meta{font-size:12px;color:var(--muted);}\n  .download-list{margin-top:10px;display:flex;flex-direction:column;gap:6px;}\n  .download-list button{align-self:flex-start;border:1px solid var(--ink);background:var(--paper-raised);color:var(--ink);border-radius:7px;padding:7px 10px;font-size:13px;font-weight:700;}\n  .download-list button:disabled{opacity:.55;cursor:not-allowed;}\n  .account-info{background:var(--paper);border:1px solid var(--line);border-radius:9px;padding:14px;margin-bottom:14px;}\n  .table-wrap{overflow-x:auto;width:100%;}\n  .status-select{padding:6px 8px;border:1px solid var(--line);border-radius:6px;background:var(--paper-raised);font:inherit;font-size:12px;}\n  .inline-actions{display:flex;gap:8px;align-items:center;min-width:180px;}\n  .mini-btn{border:1px solid var(--line);background:var(--paper-raised);border-radius:6px;padding:6px 9px;font-size:12px;font-weight:600;}\n  .muted-small{font-size:12px;color:var(--muted);}\n  .hidden{display:none !important;}\n  :focus-visible{outline:2px solid var(--amber);outline-offset:2px;}\n  @media (prefers-reduced-motion: reduce){\n    *{transition-duration:0.001ms !important; animation-duration:0.001ms !important;}\n  }\n  @media(max-width:760px){\n    .hero-inner{grid-template-columns:1fr;}\n    .hero h1{font-size:32px;}\n    .form-grid{grid-template-columns:1fr;}\n    .headbar{padding:12px 14px;gap:10px;}\n    .brand{font-size:19px;}\n    .nav-actions{gap:6px;flex-wrap:wrap;justify-content:flex-end;}\n    .icon-btn{padding:8px 9px;font-size:12px;}\n    .modal-overlay{align-items:flex-end;padding:8px 8px max(8px,env(safe-area-inset-bottom));}\n    .modal{max-height:calc(100dvh - 16px);border-radius:16px 16px 10px 10px;padding:24px 18px 22px;}\n    .modal-close{top:8px;right:8px;width:48px;height:48px;font-size:23px;}\n    .product-detail-grid{grid-template-columns:1fr;gap:18px;}\n    .product-detail-media{aspect-ratio:16/10;}\n    .product-detail-title{font-size:24px !important;margin-right:48px !important;}\n    .product-detail-footer{align-items:stretch;}\n    .product-detail-footer .product-actions{width:100%;justify-content:stretch;}\n    .product-detail-footer .product-actions button{flex:1;}\n  }\n</style>\n</head>\n<body>\n\n<header>\n  <div class=\"headbar\">\n    <div class=\"brand\">\n      <svg class=\"brand-mark\" viewBox=\"0 0 32 32\" fill=\"none\">\n        <rect x=\"4\" y=\"6\" width=\"18\" height=\"22\" rx=\"2\" fill=\"var(--amber)\"/>\n        <rect x=\"8\" y=\"3\" width=\"18\" height=\"22\" rx=\"2\" fill=\"var(--ink)\"/>\n        <line x1=\"12\" y1=\"9\" x2=\"22\" y2=\"9\" stroke=\"var(--paper)\" stroke-width=\"1.4\"/>\n        <line x1=\"12\" y1=\"13\" x2=\"22\" y2=\"13\" stroke=\"var(--paper)\" stroke-width=\"1.4\"/>\n        <line x1=\"12\" y1=\"17\" x2=\"18\" y2=\"17\" stroke=\"var(--paper)\" stroke-width=\"1.4\"/>\n      </svg>\n      Next Level notes\n    </div>\n    <div class=\"nav-actions\">\n      <button class=\"icon-btn\" id=\"accountBtn\">Account</button>\n      <button class=\"icon-btn hidden\" id=\"ordersBtn\">My orders</button>\n      <button class=\"icon-btn\" id=\"cartBtn\">Cart <span class=\"badge\" id=\"cartBadge\">0</span></button>\n    </div>\n  </div>\n</header>\n\n<section class=\"hero\">\n  <div class=\"hero-inner\">\n    <div>\n      <h1>Notes made by toppers, ready in one click.</h1>\n      <p>Handwritten notes, exam guides and e-books for every subject — buy once, download instantly, keep forever.</p>\n      <div class=\"hero-ctas\">\n        <button class=\"btn btn-primary\" onclick=\"document.getElementById('shop').scrollIntoView({behavior:'smooth'})\">Browse notes</button>\n      </div>\n    </div>\n    <svg viewBox=\"0 0 320 260\" width=\"100%\" height=\"auto\">\n      <g transform=\"rotate(-6 160 130)\">\n        <rect x=\"70\" y=\"40\" width=\"150\" height=\"190\" rx=\"8\" fill=\"var(--mint)\" opacity=\"0.35\"/>\n      </g>\n      <g transform=\"rotate(4 160 130)\">\n        <rect x=\"90\" y=\"20\" width=\"150\" height=\"190\" rx=\"8\" fill=\"var(--highlight)\" opacity=\"0.55\"/>\n      </g>\n      <rect x=\"80\" y=\"35\" width=\"150\" height=\"195\" rx=\"8\" fill=\"var(--paper-raised)\" stroke=\"var(--line)\"/>\n      <rect x=\"80\" y=\"35\" width=\"10\" height=\"195\" rx=\"4\" fill=\"var(--amber)\"/>\n      <line x1=\"105\" y1=\"65\" x2=\"205\" y2=\"65\" stroke=\"var(--line)\" stroke-width=\"2\"/>\n      <line x1=\"105\" y1=\"82\" x2=\"205\" y2=\"82\" stroke=\"var(--line)\" stroke-width=\"2\"/>\n      <line x1=\"105\" y1=\"99\" x2=\"185\" y2=\"99\" stroke=\"var(--line)\" stroke-width=\"2\"/>\n      <line x1=\"105\" y1=\"126\" x2=\"205\" y2=\"126\" stroke=\"var(--line)\" stroke-width=\"2\"/>\n      <line x1=\"105\" y1=\"143\" x2=\"205\" y2=\"143\" stroke=\"var(--line)\" stroke-width=\"2\"/>\n      <line x1=\"105\" y1=\"160\" x2=\"170\" y2=\"160\" stroke=\"var(--line)\" stroke-width=\"2\"/>\n      <circle cx=\"205\" cy=\"185\" r=\"16\" fill=\"var(--ink)\"/>\n      <text x=\"205\" y=\"190\" font-size=\"13\" fill=\"var(--paper)\" text-anchor=\"middle\" font-family=\"Inter\">₹</text>\n    </svg>\n  </div>\n</section>\n\n<div class=\"chips\" id=\"chips\"></div>\n<div class=\"grid\" id=\"productGrid\"><p class=\"empty-note\">Loading catalogue…</p></div>\n\n<footer id=\"shop\">\n  <div>Next Level notes — digital notes &amp; e-books. Orders and user data are stored through the Next Level notes API.</div>\n  <div id=\"supportFooter\" class=\"support-footer hidden\">Support: <a id=\"supportFooterLink\" href=\"#\" rel=\"noopener\"></a></div>\n</footer>\n<a id=\"supportFab\" class=\"support-fab hidden\" href=\"#\" rel=\"noopener\">Support</a>\n\n<!-- CART DRAWER -->\n<div class=\"overlay\" id=\"overlay\"></div>\n<div class=\"drawer\" id=\"cartDrawer\">\n  <div class=\"drawer-head\">\n    <h2 style=\"font-size:19px;\">Your cart</h2>\n    <button class=\"close-x\" id=\"closeCart\">✕</button>\n  </div>\n  <div class=\"drawer-body\" id=\"cartBody\"></div>\n  <div class=\"drawer-foot\">\n    <div class=\"subtotal-row\"><span>Subtotal</span><span id=\"cartSubtotal\">₹0</span></div>\n    <button class=\"btn btn-amber btn-block\" id=\"checkoutBtn\">Checkout</button>\n  </div>\n</div>\n\n<!-- LOGIN MODAL -->\n<div class=\"modal-overlay\" id=\"loginModal\">\n  <div class=\"modal\">\n    <button class=\"modal-close\" type=\"button\" data-close-modal=\"loginModal\" aria-label=\"Close\">✕</button>\n    <h2>Welcome back</h2>\n    <div class=\"sub\">Sign in to track your orders and downloads.</div>\n    <div class=\"gsi-slot\" id=\"gsiSlot\"></div>\n  </div>\n</div>\n\n<!-- ACCOUNT MODAL -->\n<div class=\"modal-overlay\" id=\"accountModal\">\n  <div class=\"modal\">\n    <button class=\"modal-close\" type=\"button\" data-close-modal=\"accountModal\" aria-label=\"Close\">✕</button>\n    <h2>Your account</h2>\n    <div class=\"sub\">Your purchases and order history are linked to your Google account.</div>\n    <div class=\"account-info\" id=\"accountInfo\"></div>\n    <button class=\"btn btn-primary btn-block\" id=\"accountOrdersBtn\">View my orders</button>\n    <button class=\"btn btn-outline btn-block\" style=\"margin-top:10px;\" id=\"logoutUserBtn\">Log out</button>\n  </div>\n</div>\n\n<!-- MY ORDERS MODAL -->\n<div class=\"modal-overlay\" id=\"ordersModal\">\n  <div class=\"modal\" style=\"max-width:620px;\">\n    <button class=\"modal-close\" type=\"button\" data-close-modal=\"ordersModal\" aria-label=\"Close\">✕</button>\n    <h2>My orders</h2>\n    <div class=\"sub\">Track payment verification and download approved purchases.</div>\n    <div id=\"myOrdersList\" class=\"order-list\"><div class=\"muted-small\">Loading…</div></div>\n  </div>\n</div>\n\n<!-- PRODUCT DETAILS MODAL -->\n<div class=\"modal-overlay\" id=\"productModal\" aria-hidden=\"true\">\n  <div class=\"modal product-detail-modal\">\n    <button class=\"modal-close\" type=\"button\" data-close-modal=\"productModal\" aria-label=\"Close product details\">✕</button>\n    <div id=\"productDetailContent\"></div>\n  </div>\n</div>\n\n<!-- CHECKOUT MODAL -->\n<div class=\"modal-overlay\" id=\"checkoutModal\">\n  <div class=\"modal\">\n    <button class=\"modal-close\" type=\"button\" data-close-modal=\"checkoutModal\" aria-label=\"Close\">✕</button>\n    <h2>Checkout</h2>\n    <div class=\"sub\" id=\"checkoutSummary\"></div>\n    <div id=\"checkoutForm\">\n      <div class=\"field\"><label>Name</label><input id=\"coName\"></div>\n      <div class=\"field\"><label>Email (for download link)</label><input id=\"coEmail\"></div>\n      <div id=\"qrLoading\" class=\"qr-loading hidden\">Generating secure UPI QR for the server-verified amount…</div>\n      <div id=\"qrError\" class=\"qr-error hidden\"></div>\n      <div id=\"upiPayBox\" class=\"success-box hidden\" style=\"background:#F3F6FB;border-color:#C9D6E8;\">\n        <div style=\"font-weight:600;margin-bottom:6px;\">Pay ₹<span id=\"payAmount\">0</span> via UPI</div>\n        <div style=\"font-size:13px;color:var(--muted);margin-bottom:10px;\">Scan this QR. The exact cart amount is generated by the server.</div>\n        <img id=\"upiQrImage\" class=\"upi-qr\" alt=\"UPI payment QR code\">\n        <div class=\"qr-note\">Amount in the QR is locked to the current server-verified cart total.</div>\n        <a id=\"upiPayLink\" class=\"btn btn-outline btn-block\" href=\"#\" style=\"text-align:center;display:block;margin-top:12px;\">Pay with UPI app</a>\n        <div style=\"font-size:12.5px;color:var(--muted);margin-top:8px;\">UPI ID: <strong id=\"upiIdDisplay\">—</strong></div>\n      </div>\n      <div class=\"field\" style=\"margin-top:14px;\"><label>UPI transaction / UTR number</label><input id=\"coUtr\" placeholder=\"e.g. 234567891234\" maxlength=\"80\" inputmode=\"text\" autocomplete=\"off\"></div>\n      <button class=\"btn btn-amber btn-block\" id=\"payBtn\">I've paid — submit order</button>\n      <div class=\"setup-note\">Payments are verified manually. After approval, download links appear automatically in My Orders.</div>\n    </div>\n    <div id=\"checkoutSuccess\" class=\"hidden\"></div>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\nconst APP_CONFIG = window.NLN_CONFIG || {};\nconst API_BASE_URL = String(APP_CONFIG.API_BASE_URL || '').replace(/\\/$/, '');\nconst GOOGLE_CLIENT_ID = APP_CONFIG.GOOGLE_CLIENT_ID || 'YOUR_GOOGLE_CLIENT_ID_HERE.apps.googleusercontent.com';\n\nconst CATEGORY_LABELS = {ebook:'E-book', handwritten:'Handwritten notes', guide:'Study guide', template:'Template', website:'Website template'};\nconst COVER_COLORS = ['#1B2333','#6FA98D','#C7842A','#5B6472','#8B6BAE'];\nconst DEFAULT_PRODUCTS = [\n  {id:'p1', title:'Class 12 Physics — Full Notes', subject:'Physics', type:'handwritten', price:149, description:'Chapter-wise handwritten notes covering the entire CBSE Class 12 Physics syllabus.'},\n  {id:'p2', title:'Organic Chemistry Crash Guide', subject:'Chemistry', type:'guide', price:199, description:'A compact revision guide for organic chemistry reactions and mechanisms.'},\n  {id:'p3', title:'Data Structures E-book', subject:'Computer Science', type:'ebook', price:249, description:'Beginner-friendly e-book on arrays, trees, graphs and common interview problems.'},\n  {id:'p4', title:'UPSC Essay Answer Templates', subject:'UPSC', type:'template', price:99, description:'Ready-to-adapt structures for scoring well in the essay paper.'}\n];\n\nlet products = [];\nlet cart = [];\nlet currentUser = null;\nlet userToken = localStorage.getItem('nln-user-token') || '';\nlet activeCategory = 'all';\nlet upiId = '';\nlet currentCheckoutQuoteId = '';\nlet currentCheckoutItems = [];\nlet checkoutFromCart = true;\nlet pendingCheckout = null;\nlet supportContact = '';\nlet supportUrl = '';\n\nfunction toast(msg){\n  const t = document.getElementById('toast');\n  t.textContent = msg;\n  t.classList.add('show');\n  setTimeout(()=>t.classList.remove('show'), 2600);\n}\nfunction money(n){ return '₹' + Number(n || 0).toLocaleString('en-IN'); }\nfunction openModal(id){\n  const el=document.getElementById(id); if(!el)return;\n  el.classList.add('open'); el.setAttribute('aria-hidden','false');\n  document.body.classList.add('modal-open');\n}\nfunction closeModal(id){\n  const el=document.getElementById(id); if(!el)return;\n  el.classList.remove('open'); el.setAttribute('aria-hidden','true');\n  if(!document.querySelector('.modal-overlay.open')) document.body.classList.remove('modal-open');\n}\nfunction closeFromControl(control){\n  const id=control && control.dataset ? control.dataset.closeModal : '';\n  if(id) closeModal(id);\n}\ndocument.addEventListener('click',event=>{\n  const closeControl=event.target.closest('[data-close-modal]');\n  if(closeControl){event.preventDefault();event.stopPropagation();closeFromControl(closeControl);return;}\n  if(event.target.classList.contains('modal-overlay')&&event.target.classList.contains('open')) closeModal(event.target.id);\n});\ndocument.addEventListener('touchend',event=>{\n  const closeControl=event.target.closest('[data-close-modal]');\n  if(!closeControl)return;\n  event.preventDefault(); event.stopPropagation(); closeFromControl(closeControl);\n},{passive:false});\ndocument.addEventListener('keydown',event=>{\n  if(event.key!=='Escape')return;\n  const open=[...document.querySelectorAll('.modal-overlay.open')].pop();\n  if(open) closeModal(open.id);\n});\nfunction escapeHtml(s){ return String(s ?? '').replace(/[&<>\"']/g, m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m])); }\nfunction safeUrl(url){\n  try{\n    const u = new URL(String(url || ''), window.location.href);\n    return ['http:','https:'].includes(u.protocol) ? u.href : '#';\n  }catch{ return '#'; }\n}\nfunction supportHref(contact, url){\n  const explicit=String(url||'').trim();\n  if(explicit){try{const u=new URL(explicit,window.location.href);if(['https:','mailto:','tel:'].includes(u.protocol))return u.href;}catch{}}\n  const c=String(contact||'').trim();\n  if(/^@[A-Za-z0-9_]{4,}$/.test(c)) return 'https://t.me/'+c.slice(1);\n  if(/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(c)) return 'mailto:'+c;\n  if(/^\\+?[0-9][0-9 ()-]{6,}$/.test(c)) return 'tel:'+c.replace(/[^+0-9]/g,'');\n  return '#';\n}\nfunction renderSupport(){\n  const footer=document.getElementById('supportFooter'),link=document.getElementById('supportFooterLink'),fab=document.getElementById('supportFab');\n  if(!supportContact){footer.classList.add('hidden');fab.classList.add('hidden');return;}\n  const href=supportHref(supportContact,supportUrl);link.textContent=supportContact;link.href=href;fab.href=href;fab.textContent='Support · '+supportContact;\n  if(href.startsWith('https://')){link.target='_blank';fab.target='_blank';}else{link.removeAttribute('target');fab.removeAttribute('target');}\n  footer.classList.remove('hidden');fab.classList.remove('hidden');\n}\nasync function loadPublicSettings(){\n  try{const data=await api('/api/settings/public');upiId=data.upiId||'';supportContact=data.supportContact||'';supportUrl=data.supportUrl||'';renderSupport();}catch{}\n}\nfunction dateText(value){\n  if(!value) return '—';\n  const d = new Date(value);\n  return Number.isNaN(d.getTime()) ? '—' : d.toLocaleString('en-IN', {dateStyle:'medium', timeStyle:'short'});\n}\nfunction statusPill(status){\n  const s = ['pending','paid','delivered','rejected'].includes(status) ? status : 'pending';\n  return `<span class=\"status-pill status-${s}\">${escapeHtml(s)}</span>`;\n}\nfunction backendConfigured(){ return !API_BASE_URL.includes('YOUR-RENDER-BACKEND'); }\n\nasync function api(path, {method='GET', body, auth='none'}={}){\n  if(!backendConfigured()) throw new Error('Backend URL is not configured in config.js');\n  const headers = {'Content-Type':'application/json'};\n  if(auth==='user' && userToken) headers.Authorization = `Bearer ${userToken}`;\n  const res = await fetch(API_BASE_URL + path, {method, headers, body: body === undefined ? undefined : JSON.stringify(body)});\n  let data = {};\n  try{ data = await res.json(); }catch{}\n  if(!res.ok){\n    if(res.status===401 && auth==='user') logoutUser(false);\n    throw new Error(data.error || `Request failed (${res.status})`);\n  }\n  return data;\n}\n\nasync function loadProducts(){\n  try{\n    const data = await api('/api/products');\n    products = data.products || [];\n  }catch(err){\n    products = DEFAULT_PRODUCTS;\n    if(backendConfigured()) toast('Could not reach backend. Showing sample catalogue.');\n  }\n  renderChips(); renderGrid();\n}\nfunction loadCart(){\n  try{ cart = JSON.parse(localStorage.getItem('nln-cart') || '[]'); }catch{ cart=[]; }\n  renderCart();\n}\nfunction saveCart(){ localStorage.setItem('nln-cart', JSON.stringify(cart)); renderCart(); }\nfunction loadUser(){\n  try{ currentUser = JSON.parse(localStorage.getItem('nln-user') || 'null'); }catch{ currentUser=null; }\n  if(!userToken) currentUser=null;\n  updateAccountBtn();\n}\nfunction saveUserSession(user, token){\n  currentUser=user; userToken=token;\n  localStorage.setItem('nln-user', JSON.stringify(user));\n  localStorage.setItem('nln-user-token', token);\n  updateAccountBtn();\n}\nfunction logoutUser(showToast=true){\n  currentUser=null; userToken='';\n  localStorage.removeItem('nln-user'); localStorage.removeItem('nln-user-token');\n  updateAccountBtn(); closeModal('accountModal'); closeModal('ordersModal');\n  if(showToast) toast('Logged out');\n}\nfunction updateAccountBtn(){\n  document.getElementById('accountBtn').textContent = currentUser ? currentUser.name.split(' ')[0] : 'Account';\n  document.getElementById('ordersBtn').classList.toggle('hidden', !currentUser);\n}\n\nfunction renderChips(){\n  const cats = ['all', ...new Set(products.map(p=>p.type))];\n  const wrap = document.getElementById('chips');\n  wrap.innerHTML = cats.map(c=>`<button class=\"chip ${c===activeCategory?'active':''}\" data-cat=\"${escapeHtml(c)}\">${escapeHtml(c==='all'?'All':(CATEGORY_LABELS[c]||c))}</button>`).join('');\n  wrap.querySelectorAll('.chip').forEach(btn=>btn.onclick=()=>{activeCategory=btn.dataset.cat;renderChips();renderGrid();});\n}\nfunction renderGrid(){\n  const grid=document.getElementById('productGrid');\n  const list=activeCategory==='all'?products:products.filter(p=>p.type===activeCategory);\n  if(!list.length){grid.innerHTML='<p class=\"empty-note\">No products here yet.</p>';return;}\n  grid.innerHTML=list.map((p,i)=>{const image=safeUrl(p.image||'');return `\n    <div class=\"card\" data-product-id=\"${escapeHtml(p.id)}\" role=\"button\" tabindex=\"0\" aria-label=\"View details for ${escapeHtml(p.title)}\">\n      <div class=\"cover ${image&&image!=='#'?'has-image':''}\" ${image&&image!=='#'?'':`style=\"background:${COVER_COLORS[i % COVER_COLORS.length]}\"`}>${image&&image!=='#'?`<img class=\"cover-img\" src=\"${escapeHtml(image)}\" alt=\"${escapeHtml(p.title)}\" loading=\"lazy\">`:''}<span class=\"tag\">${escapeHtml(CATEGORY_LABELS[p.type]||p.type)}</span></div>\n      <div class=\"card-body\">\n        <h3>${escapeHtml(p.title)}</h3><div class=\"subject\">${escapeHtml(p.subject||'')}</div>\n        <p style=\"font-size:13px;color:var(--muted);margin:4px 0 0;\">${escapeHtml((p.description||'').slice(0,80))}${(p.description||'').length>80?'…':''}</p>\n        <div class=\"card-foot\"><span class=\"price\">${money(p.price)}</span><div class=\"product-actions\"><button type=\"button\" class=\"buy-btn\" data-buy-id=\"${escapeHtml(p.id)}\">Buy now</button><button type=\"button\" class=\"add-btn\" data-id=\"${escapeHtml(p.id)}\"><span aria-hidden=\"true\">+</span> Add to cart</button></div></div>\n      </div>\n    </div>`;}).join('');\n  grid.querySelectorAll('.add-btn').forEach(btn=>btn.onclick=()=>addToCart(btn.dataset.id));\n  grid.querySelectorAll('.buy-btn').forEach(btn=>btn.onclick=()=>buyNow(btn.dataset.buyId));\n  grid.querySelectorAll('.card[data-product-id]').forEach(card=>{\n    card.onclick=event=>{if(event.target.closest('button,a'))return;openProductDetails(card.dataset.productId);};\n    card.onkeydown=event=>{if((event.key==='Enter'||event.key===' ')&&!event.target.closest('button,a')){event.preventDefault();openProductDetails(card.dataset.productId);}};\n  });\n}\nfunction openProductDetails(id){\n  const p=products.find(x=>x.id===id); if(!p){toast('Product is unavailable');return;}\n  const image=safeUrl(p.image||'');\n  const content=document.getElementById('productDetailContent');\n  content.innerHTML=`\n    <div class=\"product-detail-grid\">\n      <div class=\"product-detail-media\">${image&&image!=='#'?`<img src=\"${escapeHtml(image)}\" alt=\"${escapeHtml(p.title)}\">`:`<div class=\"product-detail-placeholder\">${escapeHtml(CATEGORY_LABELS[p.type]||p.type||'Digital product')}</div>`}</div>\n      <div>\n        <span class=\"product-detail-type\">${escapeHtml(CATEGORY_LABELS[p.type]||p.type||'Digital product')}</span>\n        <h2 class=\"product-detail-title\">${escapeHtml(p.title)}</h2>\n        <div class=\"product-detail-subject\">${escapeHtml(p.subject||'')}</div>\n        <div class=\"product-detail-description\">${escapeHtml(p.description||'No description available.')}</div>\n        <div class=\"product-detail-footer\">\n          <span class=\"product-detail-price\">${money(p.price)}</span>\n          <div class=\"product-actions\">\n            <button type=\"button\" class=\"buy-btn\" data-detail-buy>Buy now</button>\n            <button type=\"button\" class=\"add-btn\" data-detail-add><span aria-hidden=\"true\">+</span> Add to cart</button>\n          </div>\n        </div>\n      </div>\n    </div>`;\n  content.querySelector('[data-detail-add]').onclick=()=>addToCart(id);\n  content.querySelector('[data-detail-buy]').onclick=()=>{closeModal('productModal');buyNow(id);};\n  openModal('productModal');\n}\nfunction addToCart(id){\n  const existing=cart.find(c=>c.productId===id);\n  if(existing) existing.qty+=1; else cart.push({productId:id,qty:1});\n  saveCart(); toast('Added to cart');\n}\nfunction changeQty(id,delta){\n  const item=cart.find(c=>c.productId===id); if(!item)return;\n  item.qty+=delta; if(item.qty<=0) cart=cart.filter(c=>c.productId!==id); saveCart();\n}\nfunction removeFromCart(id){cart=cart.filter(c=>c.productId!==id);saveCart();}\nfunction cartTotal(){return cart.reduce((sum,c)=>{const p=products.find(p=>p.id===c.productId);return sum+(p?p.price*c.qty:0);},0);}\nfunction renderCart(){\n  const body=document.getElementById('cartBody');\n  const count=cart.reduce((n,c)=>n+c.qty,0); document.getElementById('cartBadge').textContent=count;\n  if(!cart.length){body.innerHTML='<p style=\"color:var(--muted);\">Your cart is empty.</p>';}\n  else{\n    body.innerHTML=cart.map(c=>{const p=products.find(p=>p.id===c.productId);if(!p)return'';return `\n      <div class=\"cart-item\">${p.image&&safeUrl(p.image)!=='#'?`<img class=\"cart-thumb\" src=\"${escapeHtml(safeUrl(p.image))}\" alt=\"\">`:`<div class=\"swatch\" style=\"background:${COVER_COLORS[Math.max(0,products.indexOf(p))%COVER_COLORS.length]}\"></div>`}\n      <div class=\"cart-item-info\"><h4>${escapeHtml(p.title)}</h4><div style=\"font-size:13px;color:var(--muted);\">${money(p.price)}</div>\n      <div class=\"qty-row\"><button class=\"qty-btn\" data-a=\"dec\" data-id=\"${escapeHtml(p.id)}\">−</button><span>${c.qty}</span><button class=\"qty-btn\" data-a=\"inc\" data-id=\"${escapeHtml(p.id)}\">+</button><button class=\"remove-link\" data-id=\"${escapeHtml(p.id)}\" style=\"margin-left:10px;\">Remove</button></div></div></div>`;}).join('');\n    body.querySelectorAll('.qty-btn').forEach(b=>b.onclick=()=>changeQty(b.dataset.id,b.dataset.a==='inc'?1:-1));\n    body.querySelectorAll('.remove-link').forEach(b=>b.onclick=()=>removeFromCart(b.dataset.id));\n  }\n  document.getElementById('cartSubtotal').textContent=money(cartTotal());\n}\n\n// Cart drawer\ndocument.getElementById('cartBtn').onclick=()=>{document.getElementById('cartDrawer').classList.add('open');document.getElementById('overlay').classList.add('open');};\nfunction closeDrawer(){document.getElementById('cartDrawer').classList.remove('open');document.getElementById('overlay').classList.remove('open');}\ndocument.getElementById('closeCart').onclick=closeDrawer; document.getElementById('overlay').onclick=closeDrawer;\n\n// User account / login\ndocument.getElementById('accountBtn').onclick=()=>{\n  if(!currentUser){openModal('loginModal');renderGoogleButton();return;}\n  document.getElementById('accountInfo').innerHTML=`<strong>${escapeHtml(currentUser.name)}</strong><br><span class=\"muted-small\">${escapeHtml(currentUser.email)} · ${escapeHtml(currentUser.provider||'google')}</span>`;\n  openModal('accountModal');\n};\ndocument.getElementById('ordersBtn').onclick=openMyOrders;\ndocument.getElementById('accountOrdersBtn').onclick=()=>{closeModal('accountModal');openMyOrders();};\ndocument.getElementById('logoutUserBtn').onclick=()=>logoutUser(true);\n\nfunction renderGoogleButton(){\n  const slot=document.getElementById('gsiSlot'); slot.innerHTML='';\n  try{\n    if(window.google&&google.accounts&&GOOGLE_CLIENT_ID&&!GOOGLE_CLIENT_ID.includes('YOUR_GOOGLE_CLIENT_ID')){\n      google.accounts.id.initialize({client_id:GOOGLE_CLIENT_ID,callback:handleGoogleCredential});\n      google.accounts.id.renderButton(slot,{theme:'outline',size:'large',width:320});\n    }else slot.innerHTML='<button class=\"btn btn-outline btn-block\" disabled>Sign in with Google (needs setup)</button>';\n  }catch{slot.innerHTML='<button class=\"btn btn-outline btn-block\" disabled>Sign in with Google (needs setup)</button>';}\n}\nasync function handleGoogleCredential(resp){\n  try{\n    const data=await api('/api/auth/google',{method:'POST',body:{credential:resp.credential}});\n    saveUserSession(data.user,data.userToken); closeModal('loginModal'); toast('Signed in as '+data.user.name);\n    if(pendingCheckout){const next=pendingCheckout;pendingCheckout=null;setTimeout(()=>beginCheckout(next.items,next.fromCart),0);}\n  }catch(err){toast(err.message);}\n}\nasync function openMyOrders(){\n  if(!currentUser||!userToken){openModal('loginModal');return;}\n  openModal('ordersModal');\n  const list=document.getElementById('myOrdersList'); list.innerHTML='<div class=\"muted-small\">Loading…</div>';\n  try{\n    const data=await api('/api/orders/me',{auth:'user'});\n    renderMyOrders(data.orders||[]);\n  }catch(err){list.innerHTML=`<div class=\"setup-note\">${escapeHtml(err.message)}</div>`;}\n}\nfunction renderMyOrders(orders){\n  const list=document.getElementById('myOrdersList');\n  if(!orders.length){list.innerHTML='<div class=\"muted-small\">You have no orders yet.</div>';return;}\n  list.innerHTML=orders.map(o=>{\n    const downloads=(['paid','delivered'].includes(o.status)?(o.items||[]).filter(it=>it.downloadAvailable):[]);\n    return `<div class=\"order-card\">\n      <div class=\"order-card-head\"><div><strong>${escapeHtml(o.id)}</strong><div class=\"order-meta\">${escapeHtml(dateText(o.createdAt))}</div></div>${statusPill(o.status)}</div>\n      <div style=\"font-size:13px;\">${(o.items||[]).map(it=>`${escapeHtml(it.title)} ×${Number(it.qty)||1}`).join('<br>')}</div>\n      <div style=\"display:flex;justify-content:space-between;margin-top:10px;font-weight:600;\"><span>Total</span><span>${money(o.total)}</span></div>\n      <div class=\"order-meta\" style=\"margin-top:5px;\">UTR: ${escapeHtml(o.utr||'—')}</div>\n      ${downloads.length?`<div class=\"download-list\"><strong style=\"font-size:13px;\">Downloads</strong>${downloads.map(it=>`<button type=\"button\" data-download-order=\"${escapeHtml(o.id)}\" data-download-product=\"${escapeHtml(it.productId)}\" data-download-title=\"${escapeHtml(it.title)}\">Download ${escapeHtml(it.title)}</button>`).join('')}</div>`:''}\n      ${o.status==='pending'?'<div class=\"muted-small\" style=\"margin-top:9px;\">Payment verification pending.</div>':''}\n      ${o.status==='rejected'?'<div class=\"muted-small\" style=\"margin-top:9px;color:var(--danger);\">Payment/order was rejected. Contact support if this looks wrong.</div>':''}\n    </div>`;\n  }).join('');\n  list.querySelectorAll('[data-download-order]').forEach(btn=>btn.onclick=()=>downloadPurchasedProduct(btn));\n}\nasync function downloadPurchasedProduct(btn){\n  if(!currentUser||!userToken){openModal('loginModal');renderGoogleButton();return;}\n  const orderId=btn.dataset.downloadOrder,productId=btn.dataset.downloadProduct,title=btn.dataset.downloadTitle||'product';\n  const oldText=btn.textContent;btn.disabled=true;btn.textContent='Preparing download…';\n  try{\n    const res=await fetch(`${API_BASE_URL}/api/orders/${encodeURIComponent(orderId)}/download/${encodeURIComponent(productId)}`,{\n      method:'GET',\n      headers:{Authorization:`Bearer ${userToken}`},\n      credentials:'same-origin'\n    });\n    const contentType=String(res.headers.get('content-type')||'').toLowerCase();\n    if(!res.ok){\n      let message=`Download failed (${res.status})`;\n      if(contentType.includes('application/json')){try{const data=await res.json();message=data.error||message;}catch{}}\n      if(res.status===401)logoutUser(false);\n      throw new Error(message);\n    }\n    if(contentType.includes('application/json')){\n      const data=await res.json();\n      if(data.legacyExternal&&data.externalUrl){\n        const url=safeUrl(data.externalUrl);if(url==='#')throw new Error('File unavailable');\n        window.open(url,'_blank','noopener');\n        toast('Opening legacy download');\n        return;\n      }\n      throw new Error('File unavailable');\n    }\n    const blob=await res.blob();\n    let filename=`${title}.zip`.replace(/[\\\\/:*?\"<>|]+/g,'_');\n    const encoded=res.headers.get('x-download-filename');\n    if(encoded){try{filename=decodeURIComponent(encoded);}catch{}}\n    const blobUrl=URL.createObjectURL(blob);\n    const a=document.createElement('a');a.href=blobUrl;a.download=filename;document.body.appendChild(a);a.click();a.remove();\n    setTimeout(()=>URL.revokeObjectURL(blobUrl),60000);\n    toast('Download started');\n  }catch(err){toast(err.message);}\n  finally{btn.disabled=false;btn.textContent=oldText;}\n}\n\n// Checkout\nasync function beginCheckout(items,{fromCart=false}={}){\n  const cleanItems=(items||[]).map(c=>({productId:c.productId,qty:Number(c.qty)||1}));\n  if(!cleanItems.length){toast('Nothing to checkout');return;}\n  if(!currentUser||!userToken){closeDrawer();pendingCheckout={items:cleanItems,fromCart};openModal('loginModal');renderGoogleButton();toast('Sign in before checkout');return;}\n  if(!backendConfigured()){toast('Backend is not configured');return;}\n  closeDrawer();currentCheckoutItems=cleanItems;checkoutFromCart=fromCart;\n  currentCheckoutQuoteId='';document.getElementById('checkoutForm').classList.remove('hidden');document.getElementById('checkoutSuccess').classList.add('hidden');\n  document.getElementById('checkoutSuccess').innerHTML='';document.getElementById('checkoutSummary').textContent=cleanItems.reduce((n,c)=>n+c.qty,0)+' item(s)';\n  document.getElementById('coUtr').value='';document.getElementById('coName').value=currentUser.name;document.getElementById('coEmail').value=currentUser.email;\n  document.getElementById('coName').readOnly=true;document.getElementById('coEmail').readOnly=true;\n  const upiBox=document.getElementById('upiPayBox'),loading=document.getElementById('qrLoading'),error=document.getElementById('qrError');\n  upiBox.classList.add('hidden');error.classList.add('hidden');error.textContent='';loading.classList.remove('hidden');\n  document.getElementById('upiQrImage').removeAttribute('src');document.getElementById('payBtn').disabled=true;openModal('checkoutModal');\n  try{\n    const quote=await api('/api/checkout/quote',{method:'POST',auth:'user',body:{items:cleanItems}});\n    currentCheckoutQuoteId=quote.quoteId||'';upiId=quote.upiId||'';document.getElementById('payAmount').textContent=Number(quote.total||0).toLocaleString('en-IN',{maximumFractionDigits:2});\n    document.getElementById('upiIdDisplay').textContent=upiId||'—';document.getElementById('upiPayLink').href=quote.upiUri||'#';\n    const qr=document.getElementById('upiQrImage');qr.onload=()=>loading.classList.add('hidden');qr.onerror=()=>{loading.classList.add('hidden');error.textContent='QR image could not be displayed. Use the Pay with UPI app button below.';error.classList.remove('hidden');};\n    qr.src=quote.qrDataUrl||'';loading.classList.add('hidden');upiBox.classList.remove('hidden');document.getElementById('payBtn').disabled=false;\n  }catch(err){\n    currentCheckoutQuoteId='';loading.classList.add('hidden');upiBox.classList.add('hidden');document.getElementById('upiQrImage').removeAttribute('src');document.getElementById('payAmount').textContent='—';\n    error.textContent=err.message+(supportContact?` — Support: ${supportContact}`:'');error.classList.remove('hidden');toast(err.message);\n  }\n}\nfunction buyNow(id){const p=products.find(x=>x.id===id);if(!p){toast('Product is unavailable');return;}beginCheckout([{productId:id,qty:1}],{fromCart:false});}\ndocument.getElementById('checkoutBtn').onclick=()=>{if(!cart.length){toast('Your cart is empty');return;}beginCheckout(cart,{fromCart:true});};\n\ndocument.getElementById('payBtn').onclick=async()=>{\n  const utr=document.getElementById('coUtr').value.trim(); if(!utr){toast('Enter your UPI transaction / UTR number');return;}\n  if(!currentCheckoutQuoteId){toast('Payment QR expired or was not generated. Reopen checkout.');return;}\n  const btn=document.getElementById('payBtn'); btn.disabled=true;\n  try{\n    const data=await api('/api/orders',{method:'POST',auth:'user',body:{utr,quoteId:currentCheckoutQuoteId}});\n    currentCheckoutQuoteId='';currentCheckoutItems=[];if(checkoutFromCart){cart=[];saveCart();}document.getElementById('checkoutForm').classList.add('hidden');\n    const box=document.getElementById('checkoutSuccess'); box.classList.remove('hidden');\n    box.innerHTML=`<div class=\"success-box\"><strong>Order received: ${escapeHtml(data.order.id)}</strong><br>Payment verification is pending. Check <strong>My orders</strong> for live status and download links after approval.${supportContact?`<br><br>Support: <strong>${escapeHtml(supportContact)}</strong>`:''}</div><button class=\"btn btn-primary btn-block\" style=\"margin-top:14px;\" id=\"successOrdersBtn\">View my orders</button><button class=\"btn btn-outline btn-block\" style=\"margin-top:10px;\" type=\"button\" data-close-modal=\"checkoutModal\">Done</button>`;\n    document.getElementById('successOrdersBtn').onclick=()=>{closeModal('checkoutModal');openMyOrders();};\n    toast('Order submitted for verification');\n  }catch(err){toast(err.message);}finally{btn.disabled=false;}\n};\n\n(async function init(){\n  loadCart(); loadUser(); await Promise.all([loadProducts(),loadPublicSettings()]);\n})();\n</script>\n</body>\n</html>\n","admin.html":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<meta name=\"robots\" content=\"noindex,nofollow,noarchive\">\n<title>Next Level notes Admin</title>\n<script src=\"/config.js\"></script>\n<style>\n:root{--bg:#f6f7f9;--card:#fff;--ink:#172033;--muted:#687386;--line:#e1e5eb;--accent:#c7842a;--accent-soft:#fbf3e2;--danger:#a63b32;--ok:#2f6d4c;--blue:#315f91;}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}button,input,textarea,select{font:inherit}button{cursor:pointer}\n.hidden{display:none!important}.muted{color:var(--muted)}.small{font-size:12.5px}.wrap{max-width:1180px;margin:auto;padding:24px}.card{background:var(--card);border:1px solid var(--line);border-radius:14px;box-shadow:0 4px 16px rgba(23,32,51,.04)}\n.login-shell{min-height:100vh;display:grid;place-items:center;padding:24px}.login-card{width:min(420px,100%);padding:30px}.brand{font-size:13px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);margin-bottom:10px}.login-card h1{margin:0 0 8px;font-size:28px}.login-card p{margin:0 0 24px;color:var(--muted);line-height:1.5}\n.field{margin-bottom:14px}.field label{display:block;font-size:12.5px;font-weight:700;margin-bottom:6px}.field input,.field textarea,.field select{width:100%;border:1px solid var(--line);border-radius:9px;padding:11px 12px;background:#fff;color:var(--ink);outline:none}.field textarea{min-height:90px;resize:vertical}.field input:focus,.field textarea:focus,.field select:focus{border-color:#b9a078;box-shadow:0 0 0 3px rgba(199,132,42,.10)}\n.btn{border:0;border-radius:9px;padding:10px 15px;font-weight:700}.btn-primary{background:var(--ink);color:#fff}.btn-outline{background:#fff;color:var(--ink);border:1px solid var(--line)}.btn-danger{background:#fff;color:var(--danger);border:1px solid #efd0cc}.btn-block{width:100%}.btn:disabled{opacity:.55;cursor:not-allowed}\n.topbar{background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:20}.topbar-inner{max-width:1180px;margin:auto;padding:14px 24px;display:flex;align-items:center;justify-content:space-between;gap:16px}.top-title{font-weight:800}.top-actions{display:flex;gap:8px}\n.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}.stat{padding:18px}.stat .label{font-size:12px;color:var(--muted);font-weight:700;text-transform:uppercase;letter-spacing:.04em}.stat .value{font-size:28px;font-weight:800;margin-top:6px}\n.tabs{display:flex;gap:6px;overflow:auto;border-bottom:1px solid var(--line);margin-bottom:20px}.tab{background:none;border:0;padding:12px 14px;color:var(--muted);font-weight:700;border-bottom:2px solid transparent;white-space:nowrap}.tab.active{color:var(--ink);border-color:var(--accent)}\n.section-card{padding:20px;margin-bottom:20px}.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}.section-head h2{margin:0;font-size:18px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}.span2{grid-column:1/-1}.actions{display:flex;gap:8px;flex-wrap:wrap}\n.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px;background:#fff}table{width:100%;border-collapse:collapse;font-size:13.5px;min-width:760px}th,td{text-align:left;padding:12px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:11.5px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted);background:#fafbfc}tbody tr:last-child td{border-bottom:0}.mini{padding:7px 10px;border-radius:7px;border:1px solid var(--line);background:#fff;font-weight:700;font-size:12px}.mini.danger{color:var(--danger)}\n.status{display:inline-block;padding:4px 8px;border-radius:999px;font-size:11.5px;font-weight:800;text-transform:capitalize}.pending{background:#fbf3e2;color:#8a5a16}.paid{background:#eef6f1;color:var(--ok)}.delivered{background:#eaf1fa;color:var(--blue)}.rejected{background:#fbedeb;color:var(--danger)}\n.order-filter{display:flex;gap:8px;align-items:center}.order-filter select{border:1px solid var(--line);border-radius:8px;padding:8px;background:#fff}.pager{display:flex;align-items:center;justify-content:flex-end;gap:8px;margin-top:12px}.pager .small{min-width:110px;text-align:center}\n.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,10px);background:var(--ink);color:#fff;padding:11px 18px;border-radius:9px;opacity:0;pointer-events:none;transition:.18s;z-index:100}.toast.show{opacity:1;transform:translate(-50%,0)}\n.notice{padding:12px 14px;border-radius:9px;background:var(--accent-soft);border:1px solid #efd7ad;font-size:13px;line-height:1.5}.login-error{color:var(--danger);font-size:13px;margin-top:10px;min-height:18px}\n.image-picker{display:flex;gap:16px;align-items:flex-start;flex-wrap:wrap}.image-preview{width:150px;height:110px;border:1px dashed var(--line);border-radius:10px;display:grid;place-items:center;overflow:hidden;background:#fafbfc;color:var(--muted);font-size:12px}.image-preview img{width:100%;height:100%;object-fit:cover;display:block}.product-thumb{width:58px;height:44px;object-fit:cover;border-radius:7px;border:1px solid var(--line);background:#f5f6f8}.upload-help{font-size:12px;color:var(--muted);margin-top:6px}.image-dropzone{border:2px dashed #c7ced8;border-radius:10px;padding:16px;text-align:center;background:#fafbfc;transition:.15s;outline:none}.image-dropzone.dragover{border-color:var(--accent);background:var(--accent-soft)}.image-dropzone strong{display:block;margin-bottom:4px}.image-dropzone .drop-actions{display:flex;justify-content:center;gap:8px;flex-wrap:wrap;margin-top:10px}.image-dropzone input[type=file]{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}.selected-file{font-size:12px;color:var(--ink);margin-top:8px;word-break:break-all}.package-box{border:1px solid var(--line);border-radius:10px;padding:14px;background:#fafbfc}.package-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.file-state{margin-top:8px;font-size:12.5px;line-height:1.45}.file-state.ok{color:var(--ok)}.file-state.warn{color:#8a5a16}.file-state.none{color:var(--muted)}\n@media(max-width:850px){.stats{grid-template-columns:1fr 1fr}.grid2{grid-template-columns:1fr}.span2{grid-column:auto}.wrap{padding:18px}.topbar-inner{padding:12px 18px}}@media(max-width:520px){.stats{grid-template-columns:1fr 1fr;gap:10px}.stat{padding:14px}.stat .value{font-size:23px}.top-actions .store-text{display:none}}\n</style>\n</head>\n<body>\n<div id=\"loginView\" class=\"login-shell\">\n  <div class=\"login-card card\">\n    <div class=\"brand\">Next Level notes</div>\n    <h1>Admin sign in</h1>\n    <p>This area is separate from the customer store. Enter the admin password to continue.</p>\n    <form id=\"loginForm\">\n      <div class=\"field\"><label for=\"adminPassword\">Password</label><input id=\"adminPassword\" type=\"password\" maxlength=\"128\" autocomplete=\"current-password\" required autofocus></div>\n      <button id=\"loginBtn\" class=\"btn btn-primary btn-block\" type=\"submit\">Sign in</button>\n      <div id=\"loginError\" class=\"login-error\"></div>\n    </form>\n  </div>\n</div>\n\n<div id=\"dashboardView\" class=\"hidden\">\n  <div class=\"topbar\">\n    <div class=\"topbar-inner\">\n      <div><div class=\"brand\" style=\"margin:0\">Next Level notes</div><div class=\"top-title\">Admin Dashboard</div></div>\n      <div class=\"top-actions\"><a href=\"/\" class=\"btn btn-outline\" style=\"text-decoration:none\"><span class=\"store-text\">Open </span>Store</a><button id=\"logoutBtn\" class=\"btn btn-outline\">Log out</button></div>\n    </div>\n  </div>\n  <main class=\"wrap\">\n    <section class=\"stats\">\n      <div class=\"card stat\"><div class=\"label\">Products</div><div class=\"value\" id=\"statProducts\">—</div></div>\n      <div class=\"card stat\"><div class=\"label\">Orders</div><div class=\"value\" id=\"statOrders\">—</div></div>\n      <div class=\"card stat\"><div class=\"label\">Pending</div><div class=\"value\" id=\"statPending\">—</div></div>\n      <div class=\"card stat\"><div class=\"label\">Users</div><div class=\"value\" id=\"statUsers\">—</div></div>\n    </section>\n\n    <nav class=\"tabs\">\n      <button class=\"tab active\" data-tab=\"orders\">Orders</button>\n      <button class=\"tab\" data-tab=\"products\">Products</button>\n      <button class=\"tab\" data-tab=\"users\">Users</button>\n      <button class=\"tab\" data-tab=\"settings\">Settings</button>\n    </nav>\n\n    <section id=\"tabOrders\">\n      <div class=\"section-card card\">\n        <div class=\"section-head\"><h2>Orders</h2><div class=\"order-filter\"><label class=\"small muted\" for=\"orderStatusFilter\">Status</label><select id=\"orderStatusFilter\"><option value=\"all\">All</option><option value=\"pending\">Pending</option><option value=\"paid\">Paid</option><option value=\"delivered\">Delivered</option><option value=\"rejected\">Rejected</option></select></div></div>\n        <div class=\"table-wrap\"><table><thead><tr><th>Order</th><th>Buyer</th><th>Items</th><th>Total</th><th>UTR</th><th>Status</th><th>Update</th></tr></thead><tbody id=\"orderRows\"><tr><td colspan=\"7\">Loading…</td></tr></tbody></table></div><div class=\"pager\"><button id=\"orderPrev\" class=\"mini\">Previous</button><span id=\"orderPageInfo\" class=\"small muted\">Page 1</span><button id=\"orderNext\" class=\"mini\">Next</button></div>\n      </div>\n    </section>\n\n    <section id=\"tabProducts\" class=\"hidden\">\n      <div class=\"section-card card\">\n        <div class=\"section-head\"><h2 id=\"productFormTitle\">Add product</h2></div>\n        <div class=\"grid2\">\n          <div class=\"field\"><label>Title</label><input id=\"pTitle\" maxlength=\"160\"></div>\n          <div class=\"field\"><label>Subject</label><input id=\"pSubject\" maxlength=\"120\"></div>\n          <div class=\"field\"><label>Type</label><select id=\"pType\"><option value=\"ebook\">E-book</option><option value=\"handwritten\">Handwritten notes</option><option value=\"guide\">Study guide</option><option value=\"template\">Template</option><option value=\"website\">Website template</option></select></div>\n          <div class=\"field\"><label>Price (₹)</label><input id=\"pPrice\" type=\"number\" min=\"0\" step=\"0.01\"></div>\n          <div class=\"field span2\"><label>Product image</label><div class=\"image-picker\"><div class=\"image-preview\" id=\"pImagePreview\">No image</div><div style=\"flex:1;min-width:240px\"><div id=\"imageDropzone\" class=\"image-dropzone\" tabindex=\"0\"><strong>Drop or paste an image here</strong><div class=\"upload-help\">Drag an image from Explorer, press Ctrl+V after copying an image, or choose a file.</div><div class=\"drop-actions\"><button id=\"chooseImageBtn\" type=\"button\" class=\"mini\">Choose image</button><input id=\"pImage\" type=\"file\" accept=\"image/*,.jpg,.jpeg,.png,.webp,.avif\"></div><div id=\"selectedImageName\" class=\"selected-file\"></div></div><div class=\"upload-help\">JPG, PNG, WebP or AVIF · max 2 MB. Windows File Explorer Gallery is a virtual folder, so use Pictures/Downloads, drag & drop, or paste if Gallery refuses direct file selection.</div><button id=\"removeImageBtn\" type=\"button\" class=\"mini danger hidden\" style=\"margin-top:8px\">Remove current image</button></div></div></div>\n          <div class=\"field span2\"><label>Description</label><textarea id=\"pDesc\" maxlength=\"2000\"></textarea></div>\n          <div class=\"field span2\">\n            <label>Product ZIP / File Upload</label>\n            <div class=\"package-box\">\n              <div class=\"package-row\">\n                <input id=\"pProductFile\" type=\"file\" accept=\".zip,application/zip,application/x-zip-compressed\">\n                <button id=\"removeProductFileBtn\" type=\"button\" class=\"mini danger hidden\">Remove current ZIP</button>\n              </div>\n              <div id=\"currentProductFileStatus\" class=\"file-state none\">No private ZIP uploaded.</div>\n              <div id=\"selectedProductFileName\" class=\"selected-file\"></div>\n              <div class=\"upload-help\">ZIP is stored in a private Vercel Blob store and is downloadable only through authenticated paid-order checks. Max size: <span id=\"productFileMaxLabel\">100 MB</span>.</div>\n            </div>\n          </div>\n          <div class=\"field span2\"><label>Legacy external download link (optional)</label><input id=\"pFile\" type=\"url\" maxlength=\"2000\" placeholder=\"https://...\"><div class=\"upload-help\">Only for old/external products. New products can use the private ZIP upload above.</div></div>\n        </div>\n        <div class=\"actions\"><button id=\"saveProductBtn\" class=\"btn btn-primary\">Save product</button><button id=\"cancelEditBtn\" class=\"btn btn-outline hidden\">Cancel edit</button></div>\n      </div>\n      <div class=\"section-card card\"><div class=\"section-head\"><h2>Products</h2></div><div class=\"table-wrap\"><table><thead><tr><th>Image</th><th>Title</th><th>Subject</th><th>Type</th><th>Price</th><th>Digital file</th><th>Actions</th></tr></thead><tbody id=\"productRows\"></tbody></table></div></div>\n    </section>\n\n    <section id=\"tabUsers\" class=\"hidden\">\n      <div class=\"section-card card\"><div class=\"section-head\"><h2>Users</h2></div><div class=\"table-wrap\"><table><thead><tr><th>User</th><th>Provider</th><th>Joined</th><th>Last seen</th><th>Orders</th><th>Ordered value</th></tr></thead><tbody id=\"userRows\"></tbody></table></div><div class=\"pager\"><button id=\"userPrev\" class=\"mini\">Previous</button><span id=\"userPageInfo\" class=\"small muted\">Page 1</span><button id=\"userNext\" class=\"mini\">Next</button></div></div>\n    </section>\n\n    <section id=\"tabSettings\" class=\"hidden\">\n      <div class=\"section-card card\">\n        <div class=\"section-head\"><h2>Store &amp; payment settings</h2></div>\n        <div class=\"grid2\">\n          <div class=\"field\"><label>UPI ID</label><input id=\"upiIdInput\" maxlength=\"150\" placeholder=\"yourname@upi\"></div>\n          <div class=\"field\"><label>Support contact</label><input id=\"supportContactInput\" maxlength=\"160\" placeholder=\"@your_support_bot / email / phone\"></div>\n          <div class=\"field span2\"><label>Support link (optional)</label><input id=\"supportUrlInput\" maxlength=\"500\" placeholder=\"https://t.me/your_support or mailto:support@example.com\"></div>\n        </div>\n        <button id=\"saveSettingsBtn\" class=\"btn btn-primary\">Save store settings</button>\n        <div class=\"small muted\" style=\"margin-top:8px\">Support contact is shown to customers on the store and checkout/order screens.</div>\n      </div>\n      <div class=\"section-card card\">\n        <div class=\"section-head\"><h2>Admin password</h2></div>\n        <div class=\"field\"><label>New password</label><input id=\"newAdminPass\" type=\"password\" minlength=\"12\" maxlength=\"128\" autocomplete=\"new-password\"></div><button id=\"saveAdminPassBtn\" class=\"btn btn-primary\">Change password</button>\n      </div>\n      <div class=\"notice\">Admin URL is intentionally not linked from the public storefront. The URL itself is not a security boundary; all admin data and mutations remain protected by backend authentication.</div>\n    </section>\n  </main>\n</div>\n<div id=\"toast\" class=\"toast\"></div>\n<script>\nconst APP_CONFIG = window.NLN_CONFIG || {};\nconst API_BASE_URL = String(APP_CONFIG.API_BASE_URL || '').replace(/\\/$/, '');\nlet products = [];\nlet orders = [];\nlet users = [];\nlet stats = {products:0,orders:0,pending:0,users:0};\nlet editingProductId = null;\nlet currentProductImage = '';\nlet previewObjectUrl = '';\nlet selectedProductImageFile = null;\nlet selectedProductPackageFile = null;\nlet removeCurrentProductFile = false;\nlet productFileMaxMb = 100;\nlet orderPage = 1, orderPages = 1;\nlet userPage = 1, userPages = 1;\nconst PAGE_SIZE = 50;\n\nconst $ = id => document.getElementById(id);\nfunction escapeHtml(v){return String(v??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m]));}\nfunction safeImageUrl(v){try{const u=new URL(String(v||''),window.location.href);return ['http:','https:','blob:'].includes(u.protocol)?u.href:'';}catch{return '';}}\nfunction money(v){return '₹'+Number(v||0).toLocaleString('en-IN',{maximumFractionDigits:2});}\nfunction dateText(v){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});}\nfunction toast(msg){$('toast').textContent=String(msg||'');$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2400);}\nfunction statusPill(s){const safe=['pending','paid','delivered','rejected'].includes(s)?s:'pending';return `<span class=\"status ${safe}\">${escapeHtml(safe)}</span>`;}\nfunction setLoggedOut(showMessage=true){$('dashboardView').classList.add('hidden');$('loginView').classList.remove('hidden');$('adminPassword').value='';if(showMessage)toast('Logged out');}\nasync function logout(showMessage=true){try{await fetch(API_BASE_URL+'/api/admin/logout',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:'{}'});}catch{}setLoggedOut(showMessage);}\nasync function api(path,{method='GET',body}={}){\n  const headers={'Content-Type':'application/json'};\n  const res=await fetch(API_BASE_URL+path,{method,headers,credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body)});\n  let data={};try{data=await res.json();}catch{}\n  if(!res.ok){\n    if(res.status===401&&path!=='/api/admin/login'){setLoggedOut(false);}\n    const err=new Error(data.error||`Request failed (${res.status})`);\n    err.retryAfterSeconds=Number(data.retryAfterSeconds||0);\n    err.attemptsRemaining=data.attemptsRemaining;\n    throw err;\n  }\n  return data;\n}\n\nasync function uploadProductImage(file){\n  const form=new FormData();form.append('image',file);\n  const res=await fetch(API_BASE_URL+'/api/admin/product-image',{method:'POST',credentials:'same-origin',body:form});\n  let data={};try{data=await res.json();}catch{}\n  if(!res.ok){if(res.status===401)setLoggedOut(false);throw new Error(data.error||`Image upload failed (${res.status})`);}\n  return data.image||'';\n}\nfunction setImagePreview(url){\n  const box=$('pImagePreview');const safe=safeImageUrl(url);\n  if(safe){box.innerHTML=`<img src=\"${escapeHtml(safe)}\" alt=\"Product image preview\">`;$('removeImageBtn').classList.remove('hidden');}\n  else{box.textContent='No image';$('removeImageBtn').classList.add('hidden');}\n}\nfunction clearPreviewObjectUrl(){if(previewObjectUrl){URL.revokeObjectURL(previewObjectUrl);previewObjectUrl='';}}\nfunction imageFileLooksSupported(file){\n  if(!file)return false;\n  const name=String(file.name||'').toLowerCase();\n  const type=String(file.type||'').toLowerCase();\n  return ['image/jpeg','image/png','image/webp','image/avif'].includes(type)||/\\.(?:jpe?g|png|webp|avif)$/.test(name);\n}\nfunction handleProductImageFile(file){\n  clearPreviewObjectUrl();\n  if(!file){selectedProductImageFile=null;$('selectedImageName').textContent='';setImagePreview(currentProductImage);return false;}\n  if(file.size>2*1024*1024){toast('Image must be 2 MB or smaller');selectedProductImageFile=null;$('selectedImageName').textContent='';setImagePreview(currentProductImage);return false;}\n  if(!imageFileLooksSupported(file)){toast('Use JPG, PNG, WebP or AVIF');selectedProductImageFile=null;$('selectedImageName').textContent='';setImagePreview(currentProductImage);return false;}\n  selectedProductImageFile=file;\n  $('selectedImageName').textContent=`Selected: ${file.name||'pasted-image'} (${Math.max(1,Math.round(file.size/1024))} KB)`;\n  previewObjectUrl=URL.createObjectURL(file);setImagePreview(previewObjectUrl);return true;\n}\nfunction formatBytes(bytes){\n  const n=Number(bytes||0);if(!Number.isFinite(n)||n<=0)return '0 B';\n  if(n<1024)return `${n} B`;if(n<1024*1024)return `${(n/1024).toFixed(1)} KB`;\n  return `${(n/(1024*1024)).toFixed(1)} MB`;\n}\nfunction setProductFileStatus(product){\n  const box=$('currentProductFileStatus');\n  if(removeCurrentProductFile){\n    box.className='file-state warn';box.textContent='Current private ZIP will be removed when you save.';\n    $('removeProductFileBtn').classList.add('hidden');return;\n  }\n  if(selectedProductPackageFile){\n    box.className='file-state ok';\n    box.textContent=product?.hasPrivateFile?'New ZIP selected — it will replace the current private file on save.':'New private ZIP selected.';\n    $('removeProductFileBtn').classList.toggle('hidden',!product?.hasPrivateFile);return;\n  }\n  if(product?.hasPrivateFile){\n    box.className='file-state ok';\n    box.textContent=`Private ZIP uploaded: ${product.privateFileName||'product.zip'}${product.privateFileSize?` · ${formatBytes(product.privateFileSize)}`:''}`;\n    $('removeProductFileBtn').classList.remove('hidden');return;\n  }\n  if(product?.file){\n    box.className='file-state warn';box.textContent='No private ZIP. This product currently uses a legacy external download link.';\n  }else{\n    box.className='file-state none';box.textContent='No private ZIP uploaded.';\n  }\n  $('removeProductFileBtn').classList.add('hidden');\n}\nasync function saveProductJson(path,method,body){\n  return api(path,{method,body});\n}\nfunction randomHex(bytes){const a=new Uint8Array(bytes);crypto.getRandomValues(a);return [...a].map(b=>b.toString(16).padStart(2,'0')).join('');}\nasync function uploadPrivateZip(file,onProgress){\n  let mod;\n  try{mod=await import('/vendor/blob-client.js');}\n  catch{throw new Error('Upload library missing (public/vendor/blob-client.js). Run \"npm install && npm run build:client\", commit the file and redeploy.');}\n  const pathname=`files/${randomHex(16)}.zip`;\n  const result=await mod.upload(pathname,file,{\n    access:'private',\n    handleUploadUrl:API_BASE_URL+'/api/admin/blob/upload',\n    multipart:file.size>5*1024*1024,\n    contentType:'application/zip',\n    onUploadProgress:e=>{if(onProgress)onProgress(Math.round(e.percentage||0));}\n  });\n  return {pathname:result.pathname,originalName:file.name};\n}\n\nlet loginLockTimer=null;\nfunction showLoginLock(seconds){\n  clearInterval(loginLockTimer);const btn=$('loginBtn'),input=$('adminPassword');let remaining=Math.max(1,Math.ceil(Number(seconds)||0));\n  btn.disabled=true;input.disabled=true;\n  const tick=()=>{if(remaining<=0){clearInterval(loginLockTimer);btn.disabled=false;input.disabled=false;$('loginError').textContent='You can try logging in again.';return;}const mins=Math.floor(remaining/60),secs=remaining%60;$('loginError').textContent=`Too many failed attempts. Try again in ${mins}:${String(secs).padStart(2,'0')}.`;remaining--;};\n  tick();loginLockTimer=setInterval(tick,1000);\n}\n$('loginForm').addEventListener('submit',async e=>{\n  e.preventDefault();const password=$('adminPassword').value;if(!password)return;$('loginBtn').disabled=true;$('loginError').textContent='';\n  try{await api('/api/admin/login',{method:'POST',body:{password}});$('loginView').classList.add('hidden');$('dashboardView').classList.remove('hidden');$('adminPassword').value='';await loadAll();}\n  catch(err){if(err.retryAfterSeconds>0)showLoginLock(err.retryAfterSeconds);else $('loginError').textContent=err.message;}\n  finally{if(!$('adminPassword').disabled)$('loginBtn').disabled=false;}\n});\n$('logoutBtn').onclick=()=>logout();\n\ndocument.querySelectorAll('.tab').forEach(btn=>btn.onclick=()=>{\n  document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');\n  ['orders','products','users','settings'].forEach(name=>$('tab'+name[0].toUpperCase()+name.slice(1)).classList.toggle('hidden',name!==btn.dataset.tab));\n});\n$('orderStatusFilter').onchange=async()=>{orderPage=1;await loadOrders();};\n\nasync function loadAll(){\n  try{\n    const [p,s,st]=await Promise.all([api('/api/admin/products'),api('/api/admin/settings'),api('/api/admin/stats')]);\n    products=p.products||[];productFileMaxMb=Number(p.productFileMaxMb||100);$('productFileMaxLabel').textContent=`${productFileMaxMb} MB`;$('upiIdInput').value=s.upiId||'';$('supportContactInput').value=s.supportContact||'';$('supportUrlInput').value=s.supportUrl||'';stats=st||stats;\n    await Promise.all([loadOrders(),loadUsers()]);\n    renderProducts();renderStats();\n  }catch(err){toast(err.message);}\n}\nasync function loadOrders(){\n  const status=$('orderStatusFilter').value||'all';\n  const data=await api(`/api/admin/orders?page=${orderPage}&limit=${PAGE_SIZE}&status=${encodeURIComponent(status)}`);\n  orders=data.orders||[];orderPage=Number(data.page||1);orderPages=Number(data.pages||1);renderOrders();renderOrderPager();\n}\nasync function loadUsers(){\n  const data=await api(`/api/admin/users?page=${userPage}&limit=${PAGE_SIZE}`);\n  users=data.users||[];userPage=Number(data.page||1);userPages=Number(data.pages||1);renderUsers();renderUserPager();\n}\nfunction renderStats(){$('statProducts').textContent=Number(stats.products||0);$('statOrders').textContent=Number(stats.orders||0);$('statPending').textContent=Number(stats.pending||0);$('statUsers').textContent=Number(stats.users||0);}\nfunction renderOrderPager(){$('orderPageInfo').textContent=`Page ${orderPage} of ${orderPages}`;$('orderPrev').disabled=orderPage<=1;$('orderNext').disabled=orderPage>=orderPages;}\nfunction renderUserPager(){$('userPageInfo').textContent=`Page ${userPage} of ${userPages}`;$('userPrev').disabled=userPage<=1;$('userNext').disabled=userPage>=userPages;}\n$('orderPrev').onclick=async()=>{if(orderPage>1){orderPage--;try{await loadOrders();}catch(err){toast(err.message);}}};\n$('orderNext').onclick=async()=>{if(orderPage<orderPages){orderPage++;try{await loadOrders();}catch(err){toast(err.message);}}};\n$('userPrev').onclick=async()=>{if(userPage>1){userPage--;try{await loadUsers();}catch(err){toast(err.message);}}};\n$('userNext').onclick=async()=>{if(userPage<userPages){userPage++;try{await loadUsers();}catch(err){toast(err.message);}}};\nfunction renderOrders(){\n  const rows=$('orderRows');if(!orders.length){rows.innerHTML='<tr><td colspan=\"7\" class=\"muted\">No orders found.</td></tr>';return;}\n  rows.innerHTML=orders.map(o=>`<tr><td><strong>${escapeHtml(o.id)}</strong><br><span class=\"small muted\">${escapeHtml(dateText(o.createdAt))}</span></td><td>${escapeHtml(o.buyerName||'—')}<br><span class=\"small muted\">${escapeHtml(o.buyerEmail||'—')}</span></td><td>${(o.items||[]).map(i=>`${escapeHtml(i.title)} ×${Number(i.qty)||1}`).join('<br>')}</td><td>${money(o.total)}</td><td>${escapeHtml(o.utr||'—')}</td><td>${statusPill(o.status)}</td><td><div class=\"actions\"><select class=\"mini\" data-status=\"${escapeHtml(o.id)}\">${['pending','paid','delivered','rejected'].map(s=>`<option value=\"${s}\" ${o.status===s?'selected':''}>${s}</option>`).join('')}</select><button class=\"mini\" data-save-status=\"${escapeHtml(o.id)}\">Save</button></div></td></tr>`).join('');\n  rows.querySelectorAll('[data-save-status]').forEach(btn=>btn.onclick=async()=>{const id=btn.dataset.saveStatus;const select=rows.querySelector(`[data-status=\"${CSS.escape(id)}\"]`);try{const data=await api(`/api/admin/orders/${encodeURIComponent(id)}/status`,{method:'PATCH',body:{status:select.value}});const idx=orders.findIndex(x=>x.id===id);if(idx>=0)orders[idx]=data.order;stats=await api('/api/admin/stats');renderOrders();renderStats();toast('Order status updated');}catch(err){toast(err.message);}});\n}\nfunction renderProducts(){\n  const rows=$('productRows');if(!products.length){rows.innerHTML='<tr><td colspan=\"7\" class=\"muted\">No products.</td></tr>';return;}\n  rows.innerHTML=products.map(p=>{const img=safeImageUrl(p.image);const fileState=p.hasPrivateFile?`<strong>Private ZIP</strong><br><span class=\"small muted\">${escapeHtml(p.privateFileName||'product.zip')}${p.privateFileSize?` · ${escapeHtml(formatBytes(p.privateFileSize))}`:''}</span>`:(p.file?'<span class=\"small\">Legacy external link</span>':'<span class=\"small muted\">No file</span>');return `<tr><td>${img?`<img class=\"product-thumb\" src=\"${escapeHtml(img)}\" alt=\"\">`:'—'}</td><td><strong>${escapeHtml(p.title)}</strong></td><td>${escapeHtml(p.subject||'—')}</td><td>${escapeHtml(p.type||'—')}</td><td>${money(p.price)}</td><td>${fileState}</td><td><div class=\"actions\"><button class=\"mini\" data-edit=\"${escapeHtml(p.id)}\">Edit</button><button class=\"mini danger\" data-delete=\"${escapeHtml(p.id)}\">Delete</button></div></td></tr>`;}).join('');\n  rows.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editProduct(b.dataset.edit));rows.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteProduct(b.dataset.delete));\n}\nfunction editProduct(id){\n  const p=products.find(x=>x.id===id);if(!p)return;editingProductId=id;currentProductImage=p.image||'';clearPreviewObjectUrl();\n  selectedProductPackageFile=null;removeCurrentProductFile=false;$('pProductFile').value='';$('selectedProductFileName').textContent='';\n  $('productFormTitle').textContent='Edit product';$('pTitle').value=p.title||'';$('pSubject').value=p.subject||'';$('pType').value=p.type||'ebook';$('pPrice').value=p.price??'';$('pDesc').value=p.description||'';$('pFile').value=p.file||'';$('pImage').value='';selectedProductImageFile=null;$('selectedImageName').textContent='';setImagePreview(currentProductImage);setProductFileStatus(p);$('cancelEditBtn').classList.remove('hidden');window.scrollTo({top:$('tabProducts').offsetTop-80,behavior:'smooth'});\n}\nfunction resetProductForm(){\n  editingProductId=null;currentProductImage='';clearPreviewObjectUrl();selectedProductPackageFile=null;removeCurrentProductFile=false;$('productFormTitle').textContent='Add product';['pTitle','pSubject','pPrice','pDesc','pFile'].forEach(id=>$(id).value='');$('pImage').value='';$('pProductFile').value='';selectedProductImageFile=null;$('selectedImageName').textContent='';$('selectedProductFileName').textContent='';$('pType').value='ebook';setImagePreview('');setProductFileStatus(null);$('cancelEditBtn').classList.add('hidden');\n}\n$('chooseImageBtn').onclick=()=>$('pImage').click();\n$('pImage').onchange=()=>{const file=$('pImage').files?.[0]||null;if(!handleProductImageFile(file))$('pImage').value='';};\nconst imageDropzone=$('imageDropzone');\n['dragenter','dragover'].forEach(type=>imageDropzone.addEventListener(type,e=>{e.preventDefault();e.stopPropagation();imageDropzone.classList.add('dragover');}));\n['dragleave','drop'].forEach(type=>imageDropzone.addEventListener(type,e=>{e.preventDefault();e.stopPropagation();imageDropzone.classList.remove('dragover');}));\nimageDropzone.addEventListener('drop',e=>{const file=[...(e.dataTransfer?.files||[])].find(f=>String(f.type||'').startsWith('image/')||/\\.(?:jpe?g|png|webp|avif)$/i.test(f.name||''));if(!file){toast('Drop a JPG, PNG, WebP or AVIF image');return;}$('pImage').value='';handleProductImageFile(file);});\nimageDropzone.addEventListener('paste',e=>{const file=[...(e.clipboardData?.files||[])].find(f=>String(f.type||'').startsWith('image/'));if(!file){const item=[...(e.clipboardData?.items||[])].find(i=>String(i.type||'').startsWith('image/'));if(item){const pasted=item.getAsFile();if(pasted){e.preventDefault();$('pImage').value='';handleProductImageFile(pasted);return;}}toast('Clipboard does not contain an image');return;}e.preventDefault();$('pImage').value='';handleProductImageFile(file);});\ndocument.addEventListener('paste',e=>{if($('tabProducts').classList.contains('hidden'))return;if(document.activeElement&&['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&document.activeElement!==imageDropzone)return;const item=[...(e.clipboardData?.items||[])].find(i=>String(i.type||'').startsWith('image/'));if(!item)return;const file=item.getAsFile();if(file){e.preventDefault();$('pImage').value='';handleProductImageFile(file);}});\n$('pProductFile').onchange=()=>{\n  const file=$('pProductFile').files?.[0]||null;\n  if(!file){selectedProductPackageFile=null;$('selectedProductFileName').textContent='';setProductFileStatus(products.find(x=>x.id===editingProductId));return;}\n  if(!/\\.zip$/i.test(file.name||'')){toast('Invalid ZIP: choose a .zip file');$('pProductFile').value='';selectedProductPackageFile=null;return;}\n  if(file.size>productFileMaxMb*1024*1024){toast(`File too large. Max ${productFileMaxMb} MB`);$('pProductFile').value='';selectedProductPackageFile=null;return;}\n  selectedProductPackageFile=file;removeCurrentProductFile=false;$('selectedProductFileName').textContent=`Selected: ${file.name} · ${formatBytes(file.size)}`;setProductFileStatus(products.find(x=>x.id===editingProductId));\n};\n$('removeProductFileBtn').onclick=()=>{\n  selectedProductPackageFile=null;removeCurrentProductFile=true;$('pProductFile').value='';$('selectedProductFileName').textContent='';setProductFileStatus(products.find(x=>x.id===editingProductId));\n};\n$('removeImageBtn').onclick=()=>{clearPreviewObjectUrl();currentProductImage='';selectedProductImageFile=null;$('selectedImageName').textContent='';$('pImage').value='';setImagePreview('');};\n$('cancelEditBtn').onclick=resetProductForm;\n$('saveProductBtn').onclick=async()=>{\n  const title=$('pTitle').value.trim();const price=Number($('pPrice').value);if(!title||!Number.isFinite(price)||price<0){toast('Valid title and price are required');return;}\n  const btn=$('saveProductBtn');const btnText=btn.textContent;btn.disabled=true;let uploadedImage='';\n  try{\n    let image=currentProductImage;const imageFile=selectedProductImageFile;if(imageFile){uploadedImage=await uploadProductImage(imageFile);image=uploadedImage;}\n    let privateUpload=null;\n    if(selectedProductPackageFile){privateUpload=await uploadPrivateZip(selectedProductPackageFile,pct=>{btn.textContent=`Uploading ZIP ${pct}%`;});btn.textContent='Saving…';}\n    const body={title,subject:$('pSubject').value.trim(),type:$('pType').value,price,description:$('pDesc').value.trim(),file:$('pFile').value.trim(),image,removePrivateFile:removeCurrentProductFile,privateUpload};\n    const route=editingProductId?`/api/admin/products/${encodeURIComponent(editingProductId)}`:'/api/admin/products';\n    await saveProductJson(route,editingProductId?'PUT':'POST',body);\n    const data=await api('/api/admin/products');products=data.products||[];productFileMaxMb=Number(data.productFileMaxMb||productFileMaxMb);$('productFileMaxLabel').textContent=`${productFileMaxMb} MB`;stats=await api('/api/admin/stats');resetProductForm();renderProducts();renderStats();toast('Product saved');\n  }catch(err){\n    if(uploadedImage){try{await api('/api/admin/product-image',{method:'DELETE',body:{image:uploadedImage}});}catch{}}\n    toast(err.message);\n  }finally{btn.disabled=false;btn.textContent=btnText;}\n};\nasync function deleteProduct(id){if(!confirm('Delete this product?'))return;try{await api(`/api/admin/products/${encodeURIComponent(id)}`,{method:'DELETE'});products=products.filter(p=>p.id!==id);stats=await api('/api/admin/stats');renderProducts();renderStats();toast('Product deleted');}catch(err){toast(err.message);}}\nfunction renderUsers(){const rows=$('userRows');if(!users.length){rows.innerHTML='<tr><td colspan=\"6\" class=\"muted\">No users.</td></tr>';return;}rows.innerHTML=users.map(u=>`<tr><td><strong>${escapeHtml(u.name||'—')}</strong><br><span class=\"small muted\">${escapeHtml(u.email||'—')}</span></td><td>${escapeHtml(u.provider||'guest')}</td><td>${escapeHtml(dateText(u.createdAt))}</td><td>${escapeHtml(dateText(u.lastSeenAt))}</td><td>${Number(u.orderCount)||0}</td><td>${money(u.totalOrdered)}</td></tr>`).join('');}\n$('saveSettingsBtn').onclick=async()=>{const upiId=$('upiIdInput').value.trim();const supportContact=$('supportContactInput').value.trim();const supportUrl=$('supportUrlInput').value.trim();if(!upiId){toast('Enter UPI ID');return;}try{await api('/api/admin/settings',{method:'PUT',body:{upiId,supportContact,supportUrl}});toast('Store settings saved');}catch(err){toast(err.message);}};\n$('saveAdminPassBtn').onclick=async()=>{const newPassword=$('newAdminPass').value;if(newPassword.length<12){toast('Use at least 12 characters');return;}try{await api('/api/admin/password',{method:'PUT',body:{newPassword}});$('newAdminPass').value='';setLoggedOut(false);$('loginError').textContent='Password changed. Sign in again.';}catch(err){toast(err.message);}};\n\n(async()=>{try{await api('/api/admin/settings');$('loginView').classList.add('hidden');$('dashboardView').classList.remove('hidden');await loadAll();}catch{setLoggedOut(false);}})();</script>\n</body>\n</html>\n","404.html":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n<title>Next Level notes — Study Notes &amp; E-books</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Source+Serif+4:wght@500;600;700&family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<script src=\"/config.js\"></script>\n<script src=\"https://accounts.google.com/gsi/client\" async defer></script>\n<style>\n  :root{\n    --ink:#1B2333;\n    --ink-soft:#2B3650;\n    --paper:#F8F8F5;\n    --paper-raised:#FFFFFF;\n    --line:#E1E1DB;\n    --muted:#65697A;\n    --amber:#E8A33D;\n    --amber-dark:#C7842A;\n    --mint:#6FA98D;\n    --highlight:#F4D35E;\n    --danger:#C1523E;\n    --radius:10px;\n    font-size:16px;\n  }\n  *{box-sizing:border-box;}\n  body{\n    margin:0;\n    background:var(--paper);\n    color:var(--ink);\n    font-family:'Inter',sans-serif;\n    line-height:1.5;\n  }\n  h1,h2,h3,.serif{\n    font-family:'Source Serif 4',serif;\n    margin:0;\n    color:var(--ink);\n  }\n  a{color:inherit;}\n  button{font-family:inherit;cursor:pointer;}\n  .wrap{max-width:1120px;margin:0 auto;padding:0 24px;}\n\n  /* HEADER */\n  header{\n    position:sticky;top:0;z-index:40;\n    background:var(--paper);\n    border-bottom:1px solid var(--line);\n  }\n  .headbar{display:flex;align-items:center;justify-content:space-between;padding:16px 24px;max-width:1120px;margin:0 auto;}\n  .brand{display:flex;align-items:center;gap:10px;font-family:'Source Serif 4',serif;font-weight:600;font-size:22px;}\n  .brand-mark{width:30px;height:30px;flex-shrink:0;}\n  .nav-actions{display:flex;align-items:center;gap:14px;}\n  .icon-btn{\n    position:relative;background:none;border:1px solid var(--line);border-radius:8px;\n    padding:8px 12px;font-size:14px;font-weight:500;color:var(--ink);display:flex;align-items:center;gap:6px;\n  }\n  .icon-btn:hover{border-color:var(--ink);}\n  .badge{\n    background:var(--amber);color:var(--ink);font-size:11px;font-weight:700;\n    border-radius:99px;min-width:18px;height:18px;display:inline-flex;align-items:center;justify-content:center;padding:0 5px;\n  }\n  .ghost-link{background:none;border:none;color:var(--muted);font-size:14px;text-decoration:underline;text-underline-offset:3px;}\n\n  /* HERO */\n  .hero{padding:72px 24px 60px;position:relative;overflow:hidden;}\n  .hero::before{\n    content:\"\";position:absolute;top:-120px;right:-80px;width:420px;height:420px;border-radius:50%;\n    background:radial-gradient(circle, rgba(232,163,61,0.16), transparent 70%);pointer-events:none;\n  }\n  .hero-inner{max-width:1120px;margin:0 auto;display:grid;grid-template-columns:1.1fr 0.9fr;gap:48px;align-items:center;position:relative;}\n  .hero h1{font-size:46px;line-height:1.14;font-weight:600;max-width:520px;letter-spacing:-0.01em;}\n  .hero p{color:var(--muted);font-size:17px;max-width:440px;margin-top:16px;}\n  .hero-ctas{margin-top:30px;display:flex;gap:12px;}\n  .btn{\n    border:none;border-radius:8px;padding:12px 22px;font-size:15px;font-weight:600;\n    transition:transform .15s ease, background .15s ease, box-shadow .15s ease, color .15s ease;\n  }\n  .btn:active{transform:translateY(1px);}\n  .btn-primary{background:var(--ink);color:var(--paper);box-shadow:0 1px 2px rgba(27,35,51,0.15);}\n  .btn-primary:hover{background:var(--ink-soft);box-shadow:0 4px 14px rgba(27,35,51,0.25);transform:translateY(-1px);}\n  .btn-outline{background:transparent;border:1px solid var(--ink);color:var(--ink);}\n  .btn-outline:hover{background:var(--ink);color:var(--paper);transform:translateY(-1px);}\n  .btn-amber{background:var(--amber);color:var(--ink);box-shadow:0 1px 2px rgba(199,132,42,0.25);}\n  .btn-amber:hover{background:var(--amber-dark);box-shadow:0 4px 14px rgba(199,132,42,0.35);transform:translateY(-1px);}\n  .btn-block{width:100%;}\n  .btn[disabled]{opacity:0.55;cursor:not-allowed;transform:none !important;box-shadow:none !important;}\n\n  /* CATEGORY CHIPS */\n  .chips{display:flex;gap:10px;flex-wrap:wrap;padding:0 24px 32px;max-width:1120px;margin:0 auto;}\n  .chip{\n    border:1px solid var(--line);background:var(--paper-raised);border-radius:99px;\n    padding:8px 16px;font-size:14px;font-weight:500;color:var(--muted);\n    transition:all .15s ease;\n  }\n  .chip:hover{border-color:var(--ink);color:var(--ink);}\n  .chip.active{background:var(--ink);color:var(--paper);border-color:var(--ink);box-shadow:0 2px 8px rgba(27,35,51,0.2);}\n\n  /* PRODUCT GRID */\n  .grid{\n    max-width:1120px;margin:0 auto;padding:0 24px 80px;\n    display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:24px;\n  }\n  .card{\n    background:var(--paper-raised);border:1px solid var(--line);border-radius:var(--radius);\n    overflow:hidden;display:flex;flex-direction:column;\n    transition:transform .18s ease, box-shadow .18s ease, border-color .18s ease;\n  }\n  .card:hover{transform:translateY(-4px);box-shadow:0 12px 28px rgba(27,35,51,0.12);border-color:transparent;}\n  .cover{\n    height:148px;position:relative;display:flex;align-items:flex-end;padding:14px;\n    background-image:repeating-linear-gradient(180deg, rgba(255,255,255,0.16) 0 1px, transparent 1px 22px),\n      linear-gradient(160deg, rgba(255,255,255,0.08), rgba(0,0,0,0.08));\n  }\n  .cover .tag{\n    background:rgba(255,255,255,0.92);color:var(--ink);font-size:11px;font-weight:700;\n    padding:5px 10px;border-radius:6px;letter-spacing:0.02em;box-shadow:0 2px 6px rgba(0,0,0,0.12);\n  }\n  .cover.has-image{background:#eef0f3;padding:0;align-items:flex-end;}\n  .cover.has-image::after{content:\"\";position:absolute;inset:0;background:linear-gradient(180deg,transparent 50%,rgba(0,0,0,.18));pointer-events:none;}\n  .cover-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;}\n  .cover.has-image .tag{position:relative;z-index:2;margin:14px;}\n  .cart-thumb{width:54px;height:66px;object-fit:cover;border-radius:7px;border:1px solid var(--line);background:#eef0f3;flex:0 0 auto;}\n  .upi-qr{width:min(260px,100%);height:auto;display:block;margin:12px auto;border-radius:12px;border:1px solid var(--line);background:#fff;padding:8px;}\n  .qr-note{text-align:center;font-size:12.5px;color:var(--muted);margin-top:4px;}\n  .card-body{padding:18px;display:flex;flex-direction:column;gap:6px;flex:1;}\n  .card-body h3{font-size:17px;font-weight:600;letter-spacing:-0.005em;}\n  .card-body .subject{color:var(--muted);font-size:13px;}\n  .card-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:auto;padding-top:14px;flex-wrap:wrap;}\n  .price{font-family:'Source Serif 4',serif;font-weight:600;font-size:19px;}\n  .product-actions{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end;}\n  .add-btn,.buy-btn{\n    border-radius:7px;padding:8px 12px;font-size:13px;font-weight:600;\n    display:inline-flex;align-items:center;justify-content:center;gap:6px;transition:background .15s ease, transform .15s ease,border-color .15s ease;\n  }\n  .add-btn{background:var(--ink);color:var(--paper);border:1px solid var(--ink);}\n  .buy-btn{background:var(--paper-raised);color:var(--ink);border:1px solid var(--ink);}\n  .add-btn:hover{background:var(--ink-soft);transform:translateY(-1px);}\n  .buy-btn:hover{background:#F0F2F5;transform:translateY(-1px);}\n  .add-btn:active,.buy-btn:active{transform:translateY(0);}\n  .empty-note{color:var(--muted);text-align:center;padding:60px 20px;grid-column:1/-1;}\n\n  /* CART DRAWER */\n  .overlay{\n    position:fixed;inset:0;background:rgba(27,35,51,0.35);z-index:60;\n    opacity:0;pointer-events:none;transition:opacity .2s ease;\n  }\n  .overlay.open{opacity:1;pointer-events:auto;}\n  .drawer{\n    position:fixed;top:0;right:0;height:100%;width:min(420px,92vw);\n    background:var(--paper);z-index:70;transform:translateX(100%);\n    transition:transform .28s cubic-bezier(.32,.72,0,1);display:flex;flex-direction:column;\n    border-left:1px solid var(--line);box-shadow:-8px 0 32px rgba(27,35,51,0.1);\n  }\n  .drawer.open{transform:translateX(0);}\n  .drawer-head{padding:20px 22px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;}\n  .drawer-body{flex:1;overflow-y:auto;padding:16px 22px;display:flex;flex-direction:column;gap:14px;}\n  .cart-item{display:flex;gap:12px;border-bottom:1px solid var(--line);padding-bottom:14px;}\n  .cart-item .swatch{width:48px;height:60px;border-radius:6px;flex-shrink:0;box-shadow:0 2px 6px rgba(0,0,0,0.15);}\n  .cart-item-info{flex:1;}\n  .cart-item-info h4{font-size:14px;font-weight:600;margin-bottom:2px;}\n  .qty-row{display:flex;align-items:center;gap:8px;margin-top:6px;}\n  .qty-btn{width:24px;height:24px;border:1px solid var(--line);background:none;border-radius:5px;font-size:13px;transition:border-color .15s ease;}\n  .qty-btn:hover{border-color:var(--ink);}\n  .remove-link{color:var(--danger);font-size:12px;background:none;border:none;text-decoration:underline;padding:0;}\n  .drawer-foot{padding:18px 22px;border-top:1px solid var(--line);}\n  .subtotal-row{display:flex;justify-content:space-between;font-size:15px;margin-bottom:14px;font-weight:600;}\n  .close-x{background:none;border:none;font-size:20px;color:var(--muted);line-height:1;width:30px;height:30px;border-radius:6px;transition:background .15s ease;}\n  .close-x:hover{background:var(--line);}\n\n  /* MODAL */\n  .modal-overlay{\n    position:fixed;inset:0;background:rgba(27,35,51,0.4);z-index:80;\n    display:flex;align-items:center;justify-content:center;padding:20px;\n    opacity:0;pointer-events:none;transition:opacity .18s ease;\n  }\n  .modal-overlay.open{opacity:1;pointer-events:auto;}\n  .modal{\n    background:var(--paper-raised);border-radius:14px;max-width:420px;width:100%;\n    padding:28px;position:relative;max-height:88vh;overflow-y:auto;\n    box-shadow:0 24px 60px rgba(27,35,51,0.25);\n    transform:translateY(10px) scale(.98);transition:transform .2s cubic-bezier(.32,.72,0,1);\n  }\n  .modal-overlay.open .modal{transform:translateY(0) scale(1);}\n  .modal h2{font-size:22px;margin-bottom:6px;}\n  .modal .sub{color:var(--muted);font-size:14px;margin-bottom:20px;}\n  .field{margin-bottom:14px;}\n  .field label{display:block;font-size:13px;font-weight:600;margin-bottom:5px;}\n  .field input, .field select, .field textarea{\n    width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:7px;font-size:14px;font-family:inherit;background:var(--paper);\n    transition:border-color .15s ease, box-shadow .15s ease;\n  }\n  .field input:focus, .field select:focus, .field textarea:focus{\n    outline:none;border-color:var(--amber);box-shadow:0 0 0 3px rgba(232,163,61,0.2);\n  }\n  .field textarea{resize:vertical;min-height:70px;}\n  .modal-close{position:absolute;top:14px;right:14px;background:none;border:none;font-size:20px;color:var(--muted);width:30px;height:30px;border-radius:6px;transition:background .15s ease;}\n  .modal-close:hover{background:var(--line);}\n  .divider-or{display:flex;align-items:center;gap:10px;color:var(--muted);font-size:12px;margin:16px 0;}\n  .divider-or::before,.divider-or::after{content:\"\";flex:1;height:1px;background:var(--line);}\n  .gsi-slot{display:flex;justify-content:center;min-height:40px;}\n  .setup-note{background:#FBF3E2;border:1px solid var(--highlight);border-radius:8px;padding:10px 12px;font-size:12.5px;color:var(--ink-soft);margin-top:10px;}\n  .success-box{background:#EEF6F1;border:1px solid var(--mint);border-radius:8px;padding:14px;font-size:14px;margin-top:6px;}\n  .success-box a{color:var(--ink);font-weight:600;}\n\n  .toast{\n    position:fixed;bottom:28px;left:50%;transform:translate(-50%, 12px);\n    background:var(--ink);color:var(--paper);padding:12px 22px;border-radius:8px;font-size:14px;\n    z-index:100;opacity:0;pointer-events:none;transition:opacity .2s ease, transform .2s ease;\n    box-shadow:0 10px 30px rgba(27,35,51,0.3);\n  }\n  .toast.show{opacity:1;transform:translate(-50%, 0);}\n  footer{border-top:1px solid var(--line);padding:28px 24px;text-align:center;color:var(--muted);font-size:13px;}\n  .support-footer{margin-top:8px}.support-footer a{color:var(--ink);font-weight:700;text-decoration:none}.support-footer a:hover{text-decoration:underline}\n  .support-fab{position:fixed;right:18px;bottom:18px;z-index:55;background:var(--ink);color:#fff;text-decoration:none;border-radius:999px;padding:11px 15px;font-size:13px;font-weight:700;box-shadow:0 8px 24px rgba(27,35,51,.2)}\n  .support-fab:hover{background:var(--ink-soft)}\n  .qr-loading{padding:14px;border:1px dashed var(--line);border-radius:9px;text-align:center;color:var(--muted);font-size:13px;margin-top:10px}\n  .qr-error{padding:12px 14px;border:1px solid #F0C8C4;background:#FFF2F0;color:var(--danger);border-radius:9px;font-size:13px;margin-top:10px}\n\n  .status-pill{display:inline-flex;align-items:center;padding:4px 9px;border-radius:99px;font-size:12px;font-weight:700;text-transform:capitalize;}\n  .status-pending{background:#FBF3E2;color:#8A5A16;}\n  .status-paid{background:#EEF6F1;color:#2F6D4C;}\n  .status-delivered{background:#EAF1FA;color:#315F91;}\n  .status-rejected{background:#FBEDEA;color:#9E3B2E;}\n  .order-list{display:flex;flex-direction:column;gap:12px;}\n  .order-card{border:1px solid var(--line);border-radius:10px;padding:15px;background:var(--paper);}\n  .order-card-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:8px;}\n  .order-meta{font-size:12px;color:var(--muted);}\n  .download-list{margin-top:10px;display:flex;flex-direction:column;gap:6px;}\n  .download-list a{font-size:13px;font-weight:600;color:var(--ink);}\n  .account-info{background:var(--paper);border:1px solid var(--line);border-radius:9px;padding:14px;margin-bottom:14px;}\n  .table-wrap{overflow-x:auto;width:100%;}\n  .status-select{padding:6px 8px;border:1px solid var(--line);border-radius:6px;background:var(--paper-raised);font:inherit;font-size:12px;}\n  .inline-actions{display:flex;gap:8px;align-items:center;min-width:180px;}\n  .mini-btn{border:1px solid var(--line);background:var(--paper-raised);border-radius:6px;padding:6px 9px;font-size:12px;font-weight:600;}\n  .muted-small{font-size:12px;color:var(--muted);}\n  .hidden{display:none !important;}\n  :focus-visible{outline:2px solid var(--amber);outline-offset:2px;}\n  @media (prefers-reduced-motion: reduce){\n    *{transition-duration:0.001ms !important; animation-duration:0.001ms !important;}\n  }\n  @media(max-width:760px){\n    .hero-inner{grid-template-columns:1fr;}\n    .hero h1{font-size:32px;}\n    .form-grid{grid-template-columns:1fr;}\n  }\n</style>\n</head>\n<body>\n\n<header>\n  <div class=\"headbar\">\n    <div class=\"brand\">\n      <svg class=\"brand-mark\" viewBox=\"0 0 32 32\" fill=\"none\">\n        <rect x=\"4\" y=\"6\" width=\"18\" height=\"22\" rx=\"2\" fill=\"var(--amber)\"/>\n        <rect x=\"8\" y=\"3\" width=\"18\" height=\"22\" rx=\"2\" fill=\"var(--ink)\"/>\n        <line x1=\"12\" y1=\"9\" x2=\"22\" y2=\"9\" stroke=\"var(--paper)\" stroke-width=\"1.4\"/>\n        <line x1=\"12\" y1=\"13\" x2=\"22\" y2=\"13\" stroke=\"var(--paper)\" stroke-width=\"1.4\"/>\n        <line x1=\"12\" y1=\"17\" x2=\"18\" y2=\"17\" stroke=\"var(--paper)\" stroke-width=\"1.4\"/>\n      </svg>\n      Next Level notes\n    </div>\n    <div class=\"nav-actions\">\n      <button class=\"icon-btn\" id=\"accountBtn\">Account</button>\n      <button class=\"icon-btn hidden\" id=\"ordersBtn\">My orders</button>\n      <button class=\"icon-btn\" id=\"cartBtn\">Cart <span class=\"badge\" id=\"cartBadge\">0</span></button>\n    </div>\n  </div>\n</header>\n\n<section class=\"hero\">\n  <div class=\"hero-inner\">\n    <div>\n      <h1>Notes made by toppers, ready in one click.</h1>\n      <p>Handwritten notes, exam guides and e-books for every subject — buy once, download instantly, keep forever.</p>\n      <div class=\"hero-ctas\">\n        <button class=\"btn btn-primary\" onclick=\"document.getElementById('shop').scrollIntoView({behavior:'smooth'})\">Browse notes</button>\n      </div>\n    </div>\n    <svg viewBox=\"0 0 320 260\" width=\"100%\" height=\"auto\">\n      <g transform=\"rotate(-6 160 130)\">\n        <rect x=\"70\" y=\"40\" width=\"150\" height=\"190\" rx=\"8\" fill=\"var(--mint)\" opacity=\"0.35\"/>\n      </g>\n      <g transform=\"rotate(4 160 130)\">\n        <rect x=\"90\" y=\"20\" width=\"150\" height=\"190\" rx=\"8\" fill=\"var(--highlight)\" opacity=\"0.55\"/>\n      </g>\n      <rect x=\"80\" y=\"35\" width=\"150\" height=\"195\" rx=\"8\" fill=\"var(--paper-raised)\" stroke=\"var(--line)\"/>\n      <rect x=\"80\" y=\"35\" width=\"10\" height=\"195\" rx=\"4\" fill=\"var(--amber)\"/>\n      <line x1=\"105\" y1=\"65\" x2=\"205\" y2=\"65\" stroke=\"var(--line)\" stroke-width=\"2\"/>\n      <line x1=\"105\" y1=\"82\" x2=\"205\" y2=\"82\" stroke=\"var(--line)\" stroke-width=\"2\"/>\n      <line x1=\"105\" y1=\"99\" x2=\"185\" y2=\"99\" stroke=\"var(--line)\" stroke-width=\"2\"/>\n      <line x1=\"105\" y1=\"126\" x2=\"205\" y2=\"126\" stroke=\"var(--line)\" stroke-width=\"2\"/>\n      <line x1=\"105\" y1=\"143\" x2=\"205\" y2=\"143\" stroke=\"var(--line)\" stroke-width=\"2\"/>\n      <line x1=\"105\" y1=\"160\" x2=\"170\" y2=\"160\" stroke=\"var(--line)\" stroke-width=\"2\"/>\n      <circle cx=\"205\" cy=\"185\" r=\"16\" fill=\"var(--ink)\"/>\n      <text x=\"205\" y=\"190\" font-size=\"13\" fill=\"var(--paper)\" text-anchor=\"middle\" font-family=\"Inter\">₹</text>\n    </svg>\n  </div>\n</section>\n\n<div class=\"chips\" id=\"chips\"></div>\n<div class=\"grid\" id=\"productGrid\"><p class=\"empty-note\">Loading catalogue…</p></div>\n\n<footer id=\"shop\">\n  <div>Next Level notes — digital notes &amp; e-books. Orders and user data are stored through the Next Level notes API.</div>\n  <div id=\"supportFooter\" class=\"support-footer hidden\">Support: <a id=\"supportFooterLink\" href=\"#\" rel=\"noopener\"></a></div>\n</footer>\n<a id=\"supportFab\" class=\"support-fab hidden\" href=\"#\" rel=\"noopener\">Support</a>\n\n<!-- CART DRAWER -->\n<div class=\"overlay\" id=\"overlay\"></div>\n<div class=\"drawer\" id=\"cartDrawer\">\n  <div class=\"drawer-head\">\n    <h2 style=\"font-size:19px;\">Your cart</h2>\n    <button class=\"close-x\" id=\"closeCart\">✕</button>\n  </div>\n  <div class=\"drawer-body\" id=\"cartBody\"></div>\n  <div class=\"drawer-foot\">\n    <div class=\"subtotal-row\"><span>Subtotal</span><span id=\"cartSubtotal\">₹0</span></div>\n    <button class=\"btn btn-amber btn-block\" id=\"checkoutBtn\">Checkout</button>\n  </div>\n</div>\n\n<!-- LOGIN MODAL -->\n<div class=\"modal-overlay\" id=\"loginModal\">\n  <div class=\"modal\">\n    <button class=\"modal-close\" onclick=\"closeModal('loginModal')\">✕</button>\n    <h2>Welcome back</h2>\n    <div class=\"sub\">Sign in to track your orders and downloads.</div>\n    <div class=\"gsi-slot\" id=\"gsiSlot\"></div>\n  </div>\n</div>\n\n<!-- ACCOUNT MODAL -->\n<div class=\"modal-overlay\" id=\"accountModal\">\n  <div class=\"modal\">\n    <button class=\"modal-close\" onclick=\"closeModal('accountModal')\">✕</button>\n    <h2>Your account</h2>\n    <div class=\"sub\">Your purchases and order history are linked to your Google account.</div>\n    <div class=\"account-info\" id=\"accountInfo\"></div>\n    <button class=\"btn btn-primary btn-block\" id=\"accountOrdersBtn\">View my orders</button>\n    <button class=\"btn btn-outline btn-block\" style=\"margin-top:10px;\" id=\"logoutUserBtn\">Log out</button>\n  </div>\n</div>\n\n<!-- MY ORDERS MODAL -->\n<div class=\"modal-overlay\" id=\"ordersModal\">\n  <div class=\"modal\" style=\"max-width:620px;\">\n    <button class=\"modal-close\" onclick=\"closeModal('ordersModal')\">✕</button>\n    <h2>My orders</h2>\n    <div class=\"sub\">Track payment verification and download approved purchases.</div>\n    <div id=\"myOrdersList\" class=\"order-list\"><div class=\"muted-small\">Loading…</div></div>\n  </div>\n</div>\n\n<!-- CHECKOUT MODAL -->\n<div class=\"modal-overlay\" id=\"checkoutModal\">\n  <div class=\"modal\">\n    <button class=\"modal-close\" onclick=\"closeModal('checkoutModal')\">✕</button>\n    <h2>Checkout</h2>\n    <div class=\"sub\" id=\"checkoutSummary\"></div>\n    <div id=\"checkoutForm\">\n      <div class=\"field\"><label>Name</label><input id=\"coName\"></div>\n      <div class=\"field\"><label>Email (for download link)</label><input id=\"coEmail\"></div>\n      <div id=\"qrLoading\" class=\"qr-loading hidden\">Generating secure UPI QR for the server-verified amount…</div>\n      <div id=\"qrError\" class=\"qr-error hidden\"></div>\n      <div id=\"upiPayBox\" class=\"success-box hidden\" style=\"background:#F3F6FB;border-color:#C9D6E8;\">\n        <div style=\"font-weight:600;margin-bottom:6px;\">Pay ₹<span id=\"payAmount\">0</span> via UPI</div>\n        <div style=\"font-size:13px;color:var(--muted);margin-bottom:10px;\">Scan this QR. The exact cart amount is generated by the server.</div>\n        <img id=\"upiQrImage\" class=\"upi-qr\" alt=\"UPI payment QR code\">\n        <div class=\"qr-note\">Amount in the QR is locked to the current server-verified cart total.</div>\n        <a id=\"upiPayLink\" class=\"btn btn-outline btn-block\" href=\"#\" style=\"text-align:center;display:block;margin-top:12px;\">Pay with UPI app</a>\n        <div style=\"font-size:12.5px;color:var(--muted);margin-top:8px;\">UPI ID: <strong id=\"upiIdDisplay\">—</strong></div>\n      </div>\n      <div class=\"field\" style=\"margin-top:14px;\"><label>UPI transaction / UTR number</label><input id=\"coUtr\" placeholder=\"e.g. 234567891234\" maxlength=\"80\" inputmode=\"text\" autocomplete=\"off\"></div>\n      <button class=\"btn btn-amber btn-block\" id=\"payBtn\">I've paid — submit order</button>\n      <div class=\"setup-note\">Payments are verified manually. After approval, download links appear automatically in My Orders.</div>\n    </div>\n    <div id=\"checkoutSuccess\" class=\"hidden\"></div>\n  </div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\nconst APP_CONFIG = window.NLN_CONFIG || {};\nconst API_BASE_URL = String(APP_CONFIG.API_BASE_URL || '').replace(/\\/$/, '');\nconst GOOGLE_CLIENT_ID = APP_CONFIG.GOOGLE_CLIENT_ID || 'YOUR_GOOGLE_CLIENT_ID_HERE.apps.googleusercontent.com';\n\nconst CATEGORY_LABELS = {ebook:'E-book', handwritten:'Handwritten notes', guide:'Study guide', template:'Template', website:'Website template'};\nconst COVER_COLORS = ['#1B2333','#6FA98D','#C7842A','#5B6472','#8B6BAE'];\nconst DEFAULT_PRODUCTS = [\n  {id:'p1', title:'Class 12 Physics — Full Notes', subject:'Physics', type:'handwritten', price:149, description:'Chapter-wise handwritten notes covering the entire CBSE Class 12 Physics syllabus.'},\n  {id:'p2', title:'Organic Chemistry Crash Guide', subject:'Chemistry', type:'guide', price:199, description:'A compact revision guide for organic chemistry reactions and mechanisms.'},\n  {id:'p3', title:'Data Structures E-book', subject:'Computer Science', type:'ebook', price:249, description:'Beginner-friendly e-book on arrays, trees, graphs and common interview problems.'},\n  {id:'p4', title:'UPSC Essay Answer Templates', subject:'UPSC', type:'template', price:99, description:'Ready-to-adapt structures for scoring well in the essay paper.'}\n];\n\nlet products = [];\nlet cart = [];\nlet currentUser = null;\nlet userToken = localStorage.getItem('nln-user-token') || '';\nlet activeCategory = 'all';\nlet upiId = '';\nlet currentCheckoutQuoteId = '';\nlet currentCheckoutItems = [];\nlet checkoutFromCart = true;\nlet pendingCheckout = null;\nlet supportContact = '';\nlet supportUrl = '';\n\nfunction toast(msg){\n  const t = document.getElementById('toast');\n  t.textContent = msg;\n  t.classList.add('show');\n  setTimeout(()=>t.classList.remove('show'), 2600);\n}\nfunction money(n){ return '₹' + Number(n || 0).toLocaleString('en-IN'); }\nfunction openModal(id){ document.getElementById(id).classList.add('open'); }\nfunction closeModal(id){ document.getElementById(id).classList.remove('open'); }\nfunction escapeHtml(s){ return String(s ?? '').replace(/[&<>\"']/g, m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m])); }\nfunction safeUrl(url){\n  try{\n    const u = new URL(String(url || ''), window.location.href);\n    return ['http:','https:'].includes(u.protocol) ? u.href : '#';\n  }catch{ return '#'; }\n}\nfunction supportHref(contact, url){\n  const explicit=String(url||'').trim();\n  if(explicit){try{const u=new URL(explicit,window.location.href);if(['https:','mailto:','tel:'].includes(u.protocol))return u.href;}catch{}}\n  const c=String(contact||'').trim();\n  if(/^@[A-Za-z0-9_]{4,}$/.test(c)) return 'https://t.me/'+c.slice(1);\n  if(/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(c)) return 'mailto:'+c;\n  if(/^\\+?[0-9][0-9 ()-]{6,}$/.test(c)) return 'tel:'+c.replace(/[^+0-9]/g,'');\n  return '#';\n}\nfunction renderSupport(){\n  const footer=document.getElementById('supportFooter'),link=document.getElementById('supportFooterLink'),fab=document.getElementById('supportFab');\n  if(!supportContact){footer.classList.add('hidden');fab.classList.add('hidden');return;}\n  const href=supportHref(supportContact,supportUrl);link.textContent=supportContact;link.href=href;fab.href=href;fab.textContent='Support · '+supportContact;\n  if(href.startsWith('https://')){link.target='_blank';fab.target='_blank';}else{link.removeAttribute('target');fab.removeAttribute('target');}\n  footer.classList.remove('hidden');fab.classList.remove('hidden');\n}\nasync function loadPublicSettings(){\n  try{const data=await api('/api/settings/public');upiId=data.upiId||'';supportContact=data.supportContact||'';supportUrl=data.supportUrl||'';renderSupport();}catch{}\n}\nfunction dateText(value){\n  if(!value) return '—';\n  const d = new Date(value);\n  return Number.isNaN(d.getTime()) ? '—' : d.toLocaleString('en-IN', {dateStyle:'medium', timeStyle:'short'});\n}\nfunction statusPill(status){\n  const s = ['pending','paid','delivered','rejected'].includes(status) ? status : 'pending';\n  return `<span class=\"status-pill status-${s}\">${escapeHtml(s)}</span>`;\n}\nfunction backendConfigured(){ return !API_BASE_URL.includes('YOUR-RENDER-BACKEND'); }\n\nasync function api(path, {method='GET', body, auth='none'}={}){\n  if(!backendConfigured()) throw new Error('Backend URL is not configured in config.js');\n  const headers = {'Content-Type':'application/json'};\n  if(auth==='user' && userToken) headers.Authorization = `Bearer ${userToken}`;\n  const res = await fetch(API_BASE_URL + path, {method, headers, body: body === undefined ? undefined : JSON.stringify(body)});\n  let data = {};\n  try{ data = await res.json(); }catch{}\n  if(!res.ok){\n    if(res.status===401 && auth==='user') logoutUser(false);\n    throw new Error(data.error || `Request failed (${res.status})`);\n  }\n  return data;\n}\n\nasync function loadProducts(){\n  try{\n    const data = await api('/api/products');\n    products = data.products || [];\n  }catch(err){\n    products = DEFAULT_PRODUCTS;\n    if(backendConfigured()) toast('Could not reach backend. Showing sample catalogue.');\n  }\n  renderChips(); renderGrid();\n}\nfunction loadCart(){\n  try{ cart = JSON.parse(localStorage.getItem('nln-cart') || '[]'); }catch{ cart=[]; }\n  renderCart();\n}\nfunction saveCart(){ localStorage.setItem('nln-cart', JSON.stringify(cart)); renderCart(); }\nfunction loadUser(){\n  try{ currentUser = JSON.parse(localStorage.getItem('nln-user') || 'null'); }catch{ currentUser=null; }\n  if(!userToken) currentUser=null;\n  updateAccountBtn();\n}\nfunction saveUserSession(user, token){\n  currentUser=user; userToken=token;\n  localStorage.setItem('nln-user', JSON.stringify(user));\n  localStorage.setItem('nln-user-token', token);\n  updateAccountBtn();\n}\nfunction logoutUser(showToast=true){\n  currentUser=null; userToken='';\n  localStorage.removeItem('nln-user'); localStorage.removeItem('nln-user-token');\n  updateAccountBtn(); closeModal('accountModal'); closeModal('ordersModal');\n  if(showToast) toast('Logged out');\n}\nfunction updateAccountBtn(){\n  document.getElementById('accountBtn').textContent = currentUser ? currentUser.name.split(' ')[0] : 'Account';\n  document.getElementById('ordersBtn').classList.toggle('hidden', !currentUser);\n}\n\nfunction renderChips(){\n  const cats = ['all', ...new Set(products.map(p=>p.type))];\n  const wrap = document.getElementById('chips');\n  wrap.innerHTML = cats.map(c=>`<button class=\"chip ${c===activeCategory?'active':''}\" data-cat=\"${escapeHtml(c)}\">${escapeHtml(c==='all'?'All':(CATEGORY_LABELS[c]||c))}</button>`).join('');\n  wrap.querySelectorAll('.chip').forEach(btn=>btn.onclick=()=>{activeCategory=btn.dataset.cat;renderChips();renderGrid();});\n}\nfunction renderGrid(){\n  const grid=document.getElementById('productGrid');\n  const list=activeCategory==='all'?products:products.filter(p=>p.type===activeCategory);\n  if(!list.length){grid.innerHTML='<p class=\"empty-note\">No products here yet.</p>';return;}\n  grid.innerHTML=list.map((p,i)=>{const image=safeUrl(p.image||'');return `\n    <div class=\"card\">\n      <div class=\"cover ${image&&image!=='#'?'has-image':''}\" ${image&&image!=='#'?'':`style=\"background:${COVER_COLORS[i % COVER_COLORS.length]}\"`}>${image&&image!=='#'?`<img class=\"cover-img\" src=\"${escapeHtml(image)}\" alt=\"${escapeHtml(p.title)}\" loading=\"lazy\">`:''}<span class=\"tag\">${escapeHtml(CATEGORY_LABELS[p.type]||p.type)}</span></div>\n      <div class=\"card-body\">\n        <h3>${escapeHtml(p.title)}</h3><div class=\"subject\">${escapeHtml(p.subject||'')}</div>\n        <p style=\"font-size:13px;color:var(--muted);margin:4px 0 0;\">${escapeHtml((p.description||'').slice(0,80))}${(p.description||'').length>80?'…':''}</p>\n        <div class=\"card-foot\"><span class=\"price\">${money(p.price)}</span><div class=\"product-actions\"><button class=\"buy-btn\" data-buy-id=\"${escapeHtml(p.id)}\">Buy now</button><button class=\"add-btn\" data-id=\"${escapeHtml(p.id)}\"><span aria-hidden=\"true\">+</span> Add to cart</button></div></div>\n      </div>\n    </div>`;}).join('');\n  grid.querySelectorAll('.add-btn').forEach(btn=>btn.onclick=()=>addToCart(btn.dataset.id));\n  grid.querySelectorAll('.buy-btn').forEach(btn=>btn.onclick=()=>buyNow(btn.dataset.buyId));\n}\nfunction addToCart(id){\n  const existing=cart.find(c=>c.productId===id);\n  if(existing) existing.qty+=1; else cart.push({productId:id,qty:1});\n  saveCart(); toast('Added to cart');\n}\nfunction changeQty(id,delta){\n  const item=cart.find(c=>c.productId===id); if(!item)return;\n  item.qty+=delta; if(item.qty<=0) cart=cart.filter(c=>c.productId!==id); saveCart();\n}\nfunction removeFromCart(id){cart=cart.filter(c=>c.productId!==id);saveCart();}\nfunction cartTotal(){return cart.reduce((sum,c)=>{const p=products.find(p=>p.id===c.productId);return sum+(p?p.price*c.qty:0);},0);}\nfunction renderCart(){\n  const body=document.getElementById('cartBody');\n  const count=cart.reduce((n,c)=>n+c.qty,0); document.getElementById('cartBadge').textContent=count;\n  if(!cart.length){body.innerHTML='<p style=\"color:var(--muted);\">Your cart is empty.</p>';}\n  else{\n    body.innerHTML=cart.map(c=>{const p=products.find(p=>p.id===c.productId);if(!p)return'';return `\n      <div class=\"cart-item\">${p.image&&safeUrl(p.image)!=='#'?`<img class=\"cart-thumb\" src=\"${escapeHtml(safeUrl(p.image))}\" alt=\"\">`:`<div class=\"swatch\" style=\"background:${COVER_COLORS[Math.max(0,products.indexOf(p))%COVER_COLORS.length]}\"></div>`}\n      <div class=\"cart-item-info\"><h4>${escapeHtml(p.title)}</h4><div style=\"font-size:13px;color:var(--muted);\">${money(p.price)}</div>\n      <div class=\"qty-row\"><button class=\"qty-btn\" data-a=\"dec\" data-id=\"${escapeHtml(p.id)}\">−</button><span>${c.qty}</span><button class=\"qty-btn\" data-a=\"inc\" data-id=\"${escapeHtml(p.id)}\">+</button><button class=\"remove-link\" data-id=\"${escapeHtml(p.id)}\" style=\"margin-left:10px;\">Remove</button></div></div></div>`;}).join('');\n    body.querySelectorAll('.qty-btn').forEach(b=>b.onclick=()=>changeQty(b.dataset.id,b.dataset.a==='inc'?1:-1));\n    body.querySelectorAll('.remove-link').forEach(b=>b.onclick=()=>removeFromCart(b.dataset.id));\n  }\n  document.getElementById('cartSubtotal').textContent=money(cartTotal());\n}\n\n// Cart drawer\ndocument.getElementById('cartBtn').onclick=()=>{document.getElementById('cartDrawer').classList.add('open');document.getElementById('overlay').classList.add('open');};\nfunction closeDrawer(){document.getElementById('cartDrawer').classList.remove('open');document.getElementById('overlay').classList.remove('open');}\ndocument.getElementById('closeCart').onclick=closeDrawer; document.getElementById('overlay').onclick=closeDrawer;\n\n// User account / login\ndocument.getElementById('accountBtn').onclick=()=>{\n  if(!currentUser){openModal('loginModal');renderGoogleButton();return;}\n  document.getElementById('accountInfo').innerHTML=`<strong>${escapeHtml(currentUser.name)}</strong><br><span class=\"muted-small\">${escapeHtml(currentUser.email)} · ${escapeHtml(currentUser.provider||'google')}</span>`;\n  openModal('accountModal');\n};\ndocument.getElementById('ordersBtn').onclick=openMyOrders;\ndocument.getElementById('accountOrdersBtn').onclick=()=>{closeModal('accountModal');openMyOrders();};\ndocument.getElementById('logoutUserBtn').onclick=()=>logoutUser(true);\n\nfunction renderGoogleButton(){\n  const slot=document.getElementById('gsiSlot'); slot.innerHTML='';\n  try{\n    if(window.google&&google.accounts&&GOOGLE_CLIENT_ID&&!GOOGLE_CLIENT_ID.includes('YOUR_GOOGLE_CLIENT_ID')){\n      google.accounts.id.initialize({client_id:GOOGLE_CLIENT_ID,callback:handleGoogleCredential});\n      google.accounts.id.renderButton(slot,{theme:'outline',size:'large',width:320});\n    }else slot.innerHTML='<button class=\"btn btn-outline btn-block\" disabled>Sign in with Google (needs setup)</button>';\n  }catch{slot.innerHTML='<button class=\"btn btn-outline btn-block\" disabled>Sign in with Google (needs setup)</button>';}\n}\nasync function handleGoogleCredential(resp){\n  try{\n    const data=await api('/api/auth/google',{method:'POST',body:{credential:resp.credential}});\n    saveUserSession(data.user,data.userToken); closeModal('loginModal'); toast('Signed in as '+data.user.name);\n    if(pendingCheckout){const next=pendingCheckout;pendingCheckout=null;setTimeout(()=>beginCheckout(next.items,next.fromCart),0);}\n  }catch(err){toast(err.message);}\n}\nasync function openMyOrders(){\n  if(!currentUser||!userToken){openModal('loginModal');return;}\n  openModal('ordersModal');\n  const list=document.getElementById('myOrdersList'); list.innerHTML='<div class=\"muted-small\">Loading…</div>';\n  try{\n    const data=await api('/api/orders/me',{auth:'user'});\n    renderMyOrders(data.orders||[]);\n  }catch(err){list.innerHTML=`<div class=\"setup-note\">${escapeHtml(err.message)}</div>`;}\n}\nfunction renderMyOrders(orders){\n  const list=document.getElementById('myOrdersList');\n  if(!orders.length){list.innerHTML='<div class=\"muted-small\">You have no orders yet.</div>';return;}\n  list.innerHTML=orders.map(o=>{\n    const downloads=(['paid','delivered'].includes(o.status)?(o.items||[]).filter(it=>it.file):[]);\n    return `<div class=\"order-card\">\n      <div class=\"order-card-head\"><div><strong>${escapeHtml(o.id)}</strong><div class=\"order-meta\">${escapeHtml(dateText(o.createdAt))}</div></div>${statusPill(o.status)}</div>\n      <div style=\"font-size:13px;\">${(o.items||[]).map(it=>`${escapeHtml(it.title)} ×${Number(it.qty)||1}`).join('<br>')}</div>\n      <div style=\"display:flex;justify-content:space-between;margin-top:10px;font-weight:600;\"><span>Total</span><span>${money(o.total)}</span></div>\n      <div class=\"order-meta\" style=\"margin-top:5px;\">UTR: ${escapeHtml(o.utr||'—')}</div>\n      ${downloads.length?`<div class=\"download-list\"><strong style=\"font-size:13px;\">Downloads</strong>${downloads.map(it=>`<a href=\"${escapeHtml(safeUrl(it.file))}\" target=\"_blank\" rel=\"noopener\">Download ${escapeHtml(it.title)}</a>`).join('')}</div>`:''}\n      ${o.status==='pending'?'<div class=\"muted-small\" style=\"margin-top:9px;\">Payment verification pending.</div>':''}\n      ${o.status==='rejected'?'<div class=\"muted-small\" style=\"margin-top:9px;color:var(--danger);\">Payment/order was rejected. Contact support if this looks wrong.</div>':''}\n    </div>`;\n  }).join('');\n}\n\n// Checkout\nasync function beginCheckout(items,{fromCart=false}={}){\n  const cleanItems=(items||[]).map(c=>({productId:c.productId,qty:Number(c.qty)||1}));\n  if(!cleanItems.length){toast('Nothing to checkout');return;}\n  if(!currentUser||!userToken){closeDrawer();pendingCheckout={items:cleanItems,fromCart};openModal('loginModal');renderGoogleButton();toast('Sign in before checkout');return;}\n  if(!backendConfigured()){toast('Backend is not configured');return;}\n  closeDrawer();currentCheckoutItems=cleanItems;checkoutFromCart=fromCart;\n  currentCheckoutQuoteId='';document.getElementById('checkoutForm').classList.remove('hidden');document.getElementById('checkoutSuccess').classList.add('hidden');\n  document.getElementById('checkoutSuccess').innerHTML='';document.getElementById('checkoutSummary').textContent=cleanItems.reduce((n,c)=>n+c.qty,0)+' item(s)';\n  document.getElementById('coUtr').value='';document.getElementById('coName').value=currentUser.name;document.getElementById('coEmail').value=currentUser.email;\n  document.getElementById('coName').readOnly=true;document.getElementById('coEmail').readOnly=true;\n  const upiBox=document.getElementById('upiPayBox'),loading=document.getElementById('qrLoading'),error=document.getElementById('qrError');\n  upiBox.classList.add('hidden');error.classList.add('hidden');error.textContent='';loading.classList.remove('hidden');\n  document.getElementById('upiQrImage').removeAttribute('src');document.getElementById('payBtn').disabled=true;openModal('checkoutModal');\n  try{\n    const quote=await api('/api/checkout/quote',{method:'POST',auth:'user',body:{items:cleanItems}});\n    currentCheckoutQuoteId=quote.quoteId||'';upiId=quote.upiId||'';document.getElementById('payAmount').textContent=Number(quote.total||0).toLocaleString('en-IN',{maximumFractionDigits:2});\n    document.getElementById('upiIdDisplay').textContent=upiId||'—';document.getElementById('upiPayLink').href=quote.upiUri||'#';\n    const qr=document.getElementById('upiQrImage');qr.onload=()=>loading.classList.add('hidden');qr.onerror=()=>{loading.classList.add('hidden');error.textContent='QR image could not be displayed. Use the Pay with UPI app button below.';error.classList.remove('hidden');};\n    qr.src=quote.qrDataUrl||'';loading.classList.add('hidden');upiBox.classList.remove('hidden');document.getElementById('payBtn').disabled=false;\n  }catch(err){\n    currentCheckoutQuoteId='';loading.classList.add('hidden');upiBox.classList.add('hidden');document.getElementById('upiQrImage').removeAttribute('src');document.getElementById('payAmount').textContent='—';\n    error.textContent=err.message+(supportContact?` — Support: ${supportContact}`:'');error.classList.remove('hidden');toast(err.message);\n  }\n}\nfunction buyNow(id){const p=products.find(x=>x.id===id);if(!p){toast('Product is unavailable');return;}beginCheckout([{productId:id,qty:1}],{fromCart:false});}\ndocument.getElementById('checkoutBtn').onclick=()=>{if(!cart.length){toast('Your cart is empty');return;}beginCheckout(cart,{fromCart:true});};\n\ndocument.getElementById('payBtn').onclick=async()=>{\n  const utr=document.getElementById('coUtr').value.trim(); if(!utr){toast('Enter your UPI transaction / UTR number');return;}\n  if(!currentCheckoutQuoteId){toast('Payment QR expired or was not generated. Reopen checkout.');return;}\n  const btn=document.getElementById('payBtn'); btn.disabled=true;\n  try{\n    const data=await api('/api/orders',{method:'POST',auth:'user',body:{utr,quoteId:currentCheckoutQuoteId}});\n    currentCheckoutQuoteId='';currentCheckoutItems=[];if(checkoutFromCart){cart=[];saveCart();}document.getElementById('checkoutForm').classList.add('hidden');\n    const box=document.getElementById('checkoutSuccess'); box.classList.remove('hidden');\n    box.innerHTML=`<div class=\"success-box\"><strong>Order received: ${escapeHtml(data.order.id)}</strong><br>Payment verification is pending. Check <strong>My orders</strong> for live status and download links after approval.${supportContact?`<br><br>Support: <strong>${escapeHtml(supportContact)}</strong>`:''}</div><button class=\"btn btn-primary btn-block\" style=\"margin-top:14px;\" id=\"successOrdersBtn\">View my orders</button><button class=\"btn btn-outline btn-block\" style=\"margin-top:10px;\" onclick=\"closeModal('checkoutModal')\">Done</button>`;\n    document.getElementById('successOrdersBtn').onclick=()=>{closeModal('checkoutModal');openMyOrders();};\n    toast('Order submitted for verification');\n  }catch(err){toast(err.message);}finally{btn.disabled=false;}\n};\n\n(async function init(){\n  loadCart(); loadUser(); await Promise.all([loadProducts(),loadPublicSettings()]);\n})();\n</script>\n</body>\n</html>\n"}
};
